  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler la carotte et l''oignon jaune, les couper en gros tronçons et les jeter dans une casserole avec le bouillon de volaille. Porter à frémissement, couvrir et laisser infuser vingt minutes : sans viande à pocher, c''est ce seul passage des légumes qui donnera au liquide de quoi soutenir le velouté. Filtrer au chinois et réserver au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Nettoyer les champignons de Paris frais en grattant le chapeau et en coupant le bout terreux du pied, puis les émincer en lamelles fines. Les faire sauter en deux fournées à feu vif dans la moitié du beurre doux, jusqu''à ce que toute l''eau rendue se soit évaporée et que les lamelles prennent couleur. En deux fournées et non en une : une poêle surchargée fait bouillir les champignons, et ici ils portent la garniture à eux seuls. Réserver hors du feu, l''autre moitié du beurre revenant au roux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une casserole à fond épais, fondre le reste du beurre doux à feu doux, pluvioriser la farine de blé T55 d''un coup et remuer au fouet pendant 3 minutes : le mélange doit mousser sans jamais prendre couleur, on veut un roux blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Retirer la casserole du feu et verser le bouillon chaud en filet, fouet en main, pour éviter tout grumeau. Ajouter le vin blanc sec puis le lait entier, remettre sur feu moyen et laisser réduire 15 minutes en fouettant régulièrement, jusqu''à ce que le velouté nappe le dos d''une cuillère. Assaisonner de poivre noir moulu et de muscade moulue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les champignons réservés dans le velouté, baisser au minimum et laisser les saveurs se lier 5 minutes sans que la sauce reprenne l''ébullition. La sauce, deux fois moins abondante qu''au plat de la base et liée plus serré, doit à peine napper les lamelles : trop fluide, la garniture déborderait des petites croûtes au gratinage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Battre les jaunes d''œuf cru avec la crème fraîche liquide entière dans un bol, détendre cet appareil avec une louche de sauce brûlante, puis le reverser dans la casserole hors du feu en mélangeant. Réchauffer 2 à 3 minutes à feu très doux : la sauce épaissit et prend du brillant, mais un seul bouillon ferait grainer les jaunes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Chauffer le four à 170 °C. Garnir les mini-croûtes feuilletées à ras bord, les ranger sur une plaque, parsemer chacune d''emmental râpé et enfourner de 8 à 15 minutes selon leur taille, jusqu''à ce que le fromage colore et que la garniture frémisse en surface. Servir brûlant et à la main, dès la sortie du four : une bouchée apéritive tiède retombe et détrempe sa croûte.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-009-D2', 'recipe_family', 'Bouchées apéritives aux champignons gratinées',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-009-D2', 'missing_required_count', v_missing), 'open');
  END IF;

