  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Courgettes farcies au brochet', 'Courgettes évidées farcies de chair de brochet et oignons, cuites au four dans la tomate', ds.id, 'SRC-010-D1',
    'Myko', 'editorial', 4, 25, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f874a97a985c76b5daecbc948d1d22d5',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['viande rôtie','tomate','ail']::text[],
    ARRAY['alliacé','herbacé','épicé doux']::text[], ARRAY['légume fondant','farce moelleuse','dessus doré']::text[],
    ARRAY['Courgette fraîche','Chair de brochet crue']::text[], ARRAY['La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.','La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.','La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat.']::text[],
    ARRAY['saisie','rôtissage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un plat couvert, et se réchauffe 15 minutes à 160 °C plutôt qu''au micro-ondes pour que la barquette ne s''affaisse pas. La congélation de la farce seule tient 2 mois à -18 °C ; en revanche les courgettes garnies supportent mal le gel, elles rendent leur eau et deviennent flasques à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-010'), '{"variant_label":"Version au poisson relevée dans le dossier : remplacer les viandes par de la chair de brochet crue, avec une pointe de jus de citron frais.","rationale":"La farce perd le gras du porc et le liant du bœuf : elle devient légère, presque maigre, et c''est le citron qui la tient debout à la place de la viande. Le brochet est haché cru et n''est pas passé à la poêle, sans quoi il cuirait deux fois et deviendrait cotonneux — le four s''en charge seul. Le temps de cuisson ne bouge pas pour autant : c''est la paroi de la courgette qui le fixe, et le brochet, cuit bien avant elle, demande seulement d''être couvert tôt pour ne pas sécher.","operations":[{"op":"substitute","form":"Porc haché cru","with":"Chair de brochet crue","quantity":600,"unit":"g","role":"protéine"},{"op":"remove","form":"Bœuf haché cru 15 % MG"},{"op":"add","form":"Jus de citron frais","quantity":20,"unit":"g","role":"acidité","optional":false}],"steps":[{"op":"replace","n":5,"instruction":"Retirer la poêle du feu et laisser tiédir la fondue de courgette. Hacher la chair de brochet crue au couteau, en grain un peu grossier, et la mêler à la fondue sans la remettre sur le feu : un poisson maigre saisi puis enfourné cuit deux fois et sort filandreux. Assaisonner de sel, de poivre et, si l''on y tient, d''une pincée de cumin."},{"op":"replace","n":6,"instruction":"Incorporer le persil et le basilic finement ciselés, puis le jus de citron frais, qui resserre la chair du brochet et réveille une farce que le gras de la viande ne soutient plus. Rectifier l''assaisonnement en poêlant à blanc une noisette de farce pour la goûter : une farce de poisson crue ne se juge pas à la cuillère, et une fois les barquettes au four il est trop tard pour la reprendre."},{"op":"replace","n":9,"instruction":"Enfourner cinquante minutes environ et poser une feuille d''aluminium dès la vingtième : c''est la paroi de la courgette qui commande l''horloge, non le poisson, et le brochet serait desséché bien avant qu''un centimètre de chair ne cède. La cuisson est juste quand la pointe d''un couteau traverse la peau sans effort. Laisser reposer cinq minutes avant de porter à table."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

