  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Courgettes farcies à l''orientale', 'Courgettes farcies de viande hachée relevée au cumin pour un profil épicé', ds.id, 'SRC-010-D2',
    'Myko', 'editorial', 4, 20, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', '7204bef95ed20615530578854431a2fc',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['viande rôtie','tomate','ail']::text[],
    ARRAY['alliacé','herbacé','épicé doux']::text[], ARRAY['légume fondant','farce moelleuse','dessus doré']::text[],
    ARRAY['Courgette fraîche','Porc haché cru','Bœuf haché cru 15 % MG']::text[], ARRAY['La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.','La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.','La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat.']::text[],
    ARRAY['saisie','rôtissage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un plat couvert, et se réchauffe 15 minutes à 160 °C plutôt qu''au micro-ondes pour que la barquette ne s''affaisse pas. La congélation de la farce seule tient 2 mois à -18 °C ; en revanche les courgettes garnies supportent mal le gel, elles rendent leur eau et deviennent flasques à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-010'), '{"variant_label":"Version orientale : accentuer le cumin moulu, ajouter de la coriandre fraîche ciselée et un filet de jus de citron frais au moment de servir.","rationale":"Le cumin passe de facultatif à structurant : doublé et plus, il cesse d''être une note de fond pour devenir le goût dominant de la farce, ce qui oblige à saler un peu plus pour l''équilibrer. La coriandre se partage entre la farce et le service, la moitié cuite pour le fond, la moitié crue pour la vivacité. Le citron ne va pas au four, où il ne laisserait que son amertume : il s''ajoute à table.","operations":[{"op":"set","form":"Cumin moulu","quantity":12,"role":"épice","optional":false},{"op":"add","form":"Coriandre fraîche","quantity":15,"unit":"g","role":"herbe","optional":false},{"op":"add","form":"Jus de citron frais","quantity":25,"unit":"g","role":"acidité","optional":false}],"steps":[{"op":"replace","n":6,"instruction":"Retirer la poêle du feu et mélanger à la farce encore chaude le persil, le basilic et la moitié de la coriandre fraîche, tous finement ciselés, afin qu''ils gardent leur parfum. Goûter à ce moment-là : le cumin, plus que doublé, mène désormais la farce et réclame un peu plus de sel pour ne pas y régner seul."},{"op":"insert","after":9,"instruction":"Au sortir du four, parsemer les barquettes du reste de coriandre fraîche et les asperger du jus de citron frais. Ni l''herbe crue ni l''acidité ne supportent la cuisson : ajoutées à table, elles éclaircissent le cumin au lieu de s''y dissoudre."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
