  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Courgettes rondes farcies', 'courgettes rondes farcies', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Courgettes rondes farcies', 'Courgettes rondes blanchies puis farcies de viande hachée à la tomate', ds.id, 'SRC-010-D3',
    'Myko', 'editorial', 4, 30, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e671e951e0a3ae9c136c51ab0f8bb94c',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['viande rôtie','tomate','ail']::text[],
    ARRAY['alliacé','herbacé','épicé doux']::text[], ARRAY['légume fondant','farce moelleuse','dessus doré']::text[],
    ARRAY['Courgette fraîche','Porc haché cru','Bœuf haché cru 15 % MG']::text[], ARRAY['La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.','La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.','La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat.']::text[],
    ARRAY['saisie','blanchiment','rôtissage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un plat couvert, et se réchauffe 15 minutes à 160 °C plutôt qu''au micro-ondes pour que la barquette ne s''affaisse pas. La congélation de la farce seule tient 2 mois à -18 °C ; en revanche les courgettes garnies supportent mal le gel, elles rendent leur eau et deviennent flasques à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-010'), '{"variant_label":"Avec des courgettes rondes : décalotter, évider, blanchir dix minutes à l''eau bouillante avant de garnir, puis remettre le chapeau pour la cuisson au four.","rationale":"Le contenant change et toute la méthode suit : une coque ronde a bien plus de chair à traverser qu''une barquette fendue, d''où le blanchiment préalable sans lequel elle sortirait crue au cœur. Le chapeau remis retient la vapeur et garde la farce moelleuse, mais interdit le dôme et la croûte dorée de la version en barquettes. On y gagne en tenue et en présentation, on y perd le gratiné du dessus et dix minutes de préparation.","operations":[],"steps":[{"op":"replace","n":1,"instruction":"Chauffer le four à 200 °C. Rincer les courgettes rondes sans retirer la peau, puis les décalotter au tiers supérieur d''un coup de couteau franc. Garder les chapeaux de côté, ils reviendront sur les coques à l''enfournement."},{"op":"replace","n":2,"instruction":"Évider chaque courgette à la petite cuillère en laissant une paroi d''un centimètre et sans percer le fond : une coque ronde ne tient que par son épaisseur, et une paroi trouée laisserait fuir le jus de la farce. Hacher grossièrement la pulpe recueillie et la mettre de côté."},{"op":"replace","n":4,"instruction":"Verser la pulpe de courgette hachée dans la poêle et poursuivre cinq à six minutes à feu vif, le temps que l''eau de végétation s''évapore : une farce trop humide détremperait des coques que le blanchiment a déjà gorgées d''eau."},{"op":"replace","n":7,"instruction":"Ranger les coques égouttées côte à côte dans un plat à four et les remplir de farce en tassant légèrement, jusqu''à ras bord et sans dôme : le chapeau doit pouvoir se reposer à plat dessus."},{"op":"replace","n":8,"instruction":"Écraser les tomates pelées à la fourchette et les répartir avec leur jus dans le fond du plat, autour des courgettes et non dessus. Arroser d''un filet du reste d''huile d''olive la farce encore à découvert, avant de recoiffer."},{"op":"replace","n":9,"instruction":"Poser sur chaque courgette son propre chapeau et enfourner quarante minutes environ. Le couvercle retient la vapeur et empêche la farce de sécher, mais il interdit aussi tout gratiné : inutile de guetter le brunissement, la cuisson est juste quand la pointe d''un couteau traverse la paroi sans effort. Laisser reposer cinq minutes avant de porter à table."},{"op":"insert","after":2,"instruction":"Plonger les coques et leurs chapeaux dix minutes dans une grande casserole d''eau bouillante salée, puis les égoutter tête en bas sur un linge. Une courgette ronde offre au four une paroi bien plus épaisse qu''une barquette : sans ce blanchiment, la farce serait cuite quand le légume ne le serait pas encore."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

