  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Chauffer le four à 200 °C. Rincer les courgettes rondes sans retirer la peau, puis les décalotter au tiers supérieur d''un coup de couteau franc. Garder les chapeaux de côté, ils reviendront sur les coques à l''enfournement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Évider chaque courgette à la petite cuillère en laissant une paroi d''un centimètre et sans percer le fond : une coque ronde ne tient que par son épaisseur, et une paroi trouée laisserait fuir le jus de la farce. Hacher grossièrement la pulpe recueillie et la mettre de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Plonger les coques et leurs chapeaux dix minutes dans une grande casserole d''eau bouillante salée, puis les égoutter tête en bas sur un linge. Une courgette ronde offre au four une paroi bien plus épaisse qu''une barquette : sans ce blanchiment, la farce serait cuite quand le légume ne le serait pas encore.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Tailler l''oignon et l''échalote en petits dés, écraser puis hacher les gousses d''ail. Les faire suer à feu moyen dans la moitié de l''huile d''olive, sans coloration, jusqu''à ce qu''ils deviennent translucides.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser la pulpe de courgette hachée dans la poêle et poursuivre cinq à six minutes à feu vif, le temps que l''eau de végétation s''évapore : une farce trop humide détremperait des coques que le blanchiment a déjà gorgées d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Incorporer les deux viandes hachées et les écraser à la fourchette au fur et à mesure pour qu''aucun paquet ne subsiste. Assaisonner de sel, de poivre et de cumin, puis cuire une dizaine de minutes jusqu''à disparition complète du rosé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer la poêle du feu et mélanger le persil et le basilic finement ciselés à la farce encore chaude, afin qu''ils gardent leur parfum. Goûter et rectifier l''assaisonnement à ce moment-là.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Ranger les coques égouttées côte à côte dans un plat à four et les remplir de farce en tassant légèrement, jusqu''à ras bord et sans dôme : le chapeau doit pouvoir se reposer à plat dessus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Écraser les tomates pelées à la fourchette et les répartir avec leur jus dans le fond du plat, autour des courgettes et non dessus. Arroser d''un filet du reste d''huile d''olive la farce encore à découvert, avant de recoiffer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Poser sur chaque courgette son propre chapeau et enfourner quarante minutes environ. Le couvercle retient la vapeur et empêche la farce de sécher, mais il interdit aussi tout gratiné : inutile de guetter le brunissement, la cuisson est juste quand la pointe d''un couteau traverse la paroi sans effort. Laisser reposer cinq minutes avant de porter à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-010-D3', 'recipe_family', 'Courgettes rondes farcies',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-010-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-010-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-010-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e671e951e0a3ae9c136c51ab0f8bb94c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["viande rôtie","tomate","ail"],"aroma_families":["alliacé","herbacé","épicé doux"],"target_textures":["légume fondant","farce moelleuse","dessus doré"],"signature_ingredients":["Courgette fraîche","Porc haché cru","Bœuf haché cru 15 % MG"],"identity_guardrails":["La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.","La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.","La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
