DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Anchoïade au citron', 'anchoiade au citron', 'France', 'France',
     'meal', 'condiment', 'documented_variation', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Anchoïade au citron', 'Anchoïade d''anchois et ail à l''huile d''olive, acidulée au jus de citron plutôt qu''au vinaigre', ds.id, 'SRC-007-D2',
    'Myko', 'editorial', 4, 15, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd7e287fa0f8581406a9a33829d408836',
    '{"sweet":0,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":4,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['aillé','salin','acidulé']::text[],
    ARRAY['allium','fruité vert','vinaigré']::text[], ARRAY['pommade lisse','onctueux']::text[],
    ARRAY['Anchois à l''huile, égoutté','Ail cru','Huile d''olive vierge extra']::text[], ARRAY['Sans filets d''anchois pilés, ce n''est pas une anchoïade mais une pâte d''ail à l''huile.','L''ail reste cru et réduit en pâte : le confire efface le mordant qui fait le plat.','L''huile s''incorpore en filet pour que la préparation prenne ; versée d''un coup, elle rejette son gras.','Le plat se sert froid ou à température ambiante — servi chaud, il bascule vers une bagna cauda.']::text[],
    ARRAY['émulsion']::text[], ARRAY[]::text[], ARRAY['poisson','gluten','sulfites']::text[],
    'Se garde 3 à 4 jours au réfrigérateur entre 0 et 4 °C, dans un bocal hermétique, la surface recouverte d''une fine couche d''huile d''olive qui protège de l''oxydation. Sortir 20 minutes avant de servir, l''huile figeant au froid. La congélation est déconseillée : l''émulsion se casse au dégel et l''ail cru y développe une amertume marquée.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-007'), '{"variant_label":"Version au jus de citron frais en remplacement du vinaigre de vin rouge, plus ronde en bouche","rationale":"Le citron acidifie moins franchement que le vinaigre et parfume au lieu de piquer : il en faut trois fois plus pour tenir l''anchois, et l''attaque devient ronde là où elle était sèche. Ce surcroît de liquide oblige à garder la mie, qui passe de secours facultatif à ingrédient obligatoire — sans elle la pommade resterait lâche. La contrepartie est ailleurs que dans la conservation, que le sel des anchois et la couche d''huile assurent de toute façon : le parfum du citron s''émousse au bout d''un jour ou deux, là où le vinaigre gardait sa vivacité jusqu''au fond du bocal.","operations":[{"op":"remove","form":"Vinaigre de vin rouge"},{"op":"set","form":"Jus de citron frais","quantity":28,"role":"acidifiant","optional":false},{"op":"set","form":"Pain de mie","quantity":50,"role":"liant","optional":false}],"steps":[{"op":"replace","n":2,"instruction":"Émietter la mie du pain de mie dans un bol, l''arroser des trois quarts du jus de citron frais, laisser gonfler deux minutes, puis l''incorporer à la pâte d''ail en écrasant à la fourchette jusqu''à une masse homogène et sans grumeau. Le citron mouille bien davantage qu''un acide fort : c''est la mie qui le reprend, sans quoi la pommade n''épaissirait jamais."},{"op":"replace","n":4,"instruction":"Détendre d''une cuillère d''eau froide si la texture devient trop tendue, puis ajouter la tomate râpée soigneusement égouttée pour une version plus fraîche. Rectifier au poivre noir moulu et, si le mordant manque encore, aux dernières gouttes de citron gardées à part — ajoutées en fin de course, elles restent vives au lieu de se fondre."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
