  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, installer la langue dans un grand récipient, la noyer sous l''eau froide additionnée de tout le vinaigre blanc, puis la laisser dégorger au réfrigérateur une nuit entière en renouvelant l''eau une ou deux fois. Le blanc reste ici à sa place : il dégorge sans rien colorer, là où un vinaigre teinté marquerait la chair pour rien.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Le lendemain, jeter l''eau de trempage, rincer la pièce et la remettre dans une cocotte sous une hauteur d''eau froide propre. Porter à frémissement et compter un quart d''heure, en retirant l''écume grise qui remonte, puis égoutter et rincer de nouveau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Piquer l''oignon jaune épluché des clous de girofle. Replacer la langue dans la cocotte avec cet oignon, la carotte pelée coupée en gros tronçons, le laurier, le thym, les grains de poivre et le bouillon de bœuf émietté. Recouvrir largement d''eau chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Maintenir un frémissement discret, couvercle entrouvert, pendant deux heures à deux heures trente : la lame d''un couteau doit traverser la partie la plus épaisse sans résistance. Laisser tiédir la pièce dans son bouillon pour qu''elle reste moelleuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir la langue encore chaude, la poser côté bombé contre la planche et retirer la membrane épaisse, qui se décolle alors sans effort. Parer la base, réserver au chaud. Filtrer un litre de bouillon de cuisson et le garder frémissant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pour la sauce, fondre le beurre doux dans une casserole à fond épais, y faire suer les échalotes ciselées sans qu''elles prennent couleur, puis mouiller avec le vin blanc et le vinaigre de vin rouge. Laisser réduire jusqu''à ce qu''il ne subsiste qu''un fond sirupeux, presque brun : c''est en s''évaporant que l''acide perd son agressivité et ne garde que sa profondeur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pluvioriser la farine sur les échalotes, remuer deux minutes à feu doux pour cuire le roux, incorporer le concentré de tomate, puis verser le bouillon filtré louche après louche en fouettant. Laisser épaissir vingt minutes à petit feu, en remuant régulièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hors du bouillonnement, ajouter les cornichons taillés en fines rondelles pour qu''ils gardent leur mordant, rectifier en sel fin et poivre noir moulu, puis parsemer de persil haché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Détailler la langue en tranches d''un demi-centimètre, les ranger en éventail dans un plat chaud et les napper généreusement de sauce piquante ; servir le reste de sauce à part en saucière.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-013-D1', 'recipe_family', 'Langue de bœuf sauce piquante au vinaigre de vin rouge',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-013-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-013-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-013-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('951fdfa25e143dc9d4f0cbdf18904dbf'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["acidité vinaigrée","umami de bouillon de bœuf","cornichon saumuré","aromates de court-bouillon"],"aroma_families":["vinaigré","épices chaudes","herbacé"],"target_textures":["viande fondante","sauce nappante","éclats croquants de cornichon"],"signature_ingredients":["Langue de bœuf crue","Cornichon au vinaigre","Vinaigre blanc"],"identity_guardrails":["Sans langue de bœuf pochée puis pelée, le plat n''existe plus : aucune autre pièce de bœuf ne peut s''y substituer.","Sans l''acidité conjointe du vinaigre réduit et des cornichons, la sauce n''est plus piquante mais une simple sauce brune.","La sauce doit être liée au roux avec le bouillon de cuisson de la langue, et non avec un fond étranger : c''est ce recyclage qui fait sa profondeur."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Langue de bœuf à la tomate et au piment', 'langue de boeuf a la tomate et au piment', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Langue de bœuf à la tomate et au piment', 'Langue de bœuf pochée puis mijotée dans une sauce tomate légèrement pimentée', ds.id, 'SRC-013-D2',
    'Myko', 'editorial', 6, 35, 180, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'fb31b303885e3a8703bb11837d7a9ed8',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['acidité vinaigrée','umami de bouillon de bœuf','cornichon saumuré','aromates de court-bouillon']::text[],
    ARRAY['vinaigré','épices chaudes','herbacé']::text[], ARRAY['viande fondante','sauce nappante','éclats croquants de cornichon']::text[],
    ARRAY['Langue de bœuf crue','Cornichon au vinaigre','Vinaigre blanc']::text[], ARRAY['Sans langue de bœuf pochée puis pelée, le plat n''existe plus : aucune autre pièce de bœuf ne peut s''y substituer.','Sans l''acidité conjointe du vinaigre réduit et des cornichons, la sauce n''est plus piquante mais une simple sauce brune.','La sauce doit être liée au roux avec le bouillon de cuisson de la langue, et non avec un fond étranger : c''est ce recyclage qui fait sa profondeur.']::text[],
    ARRAY['blanchiment','pochage','réduction','déglaçage','mijotage','évaporation']::text[], ARRAY[]::text[], ARRAY['gluten','lait','sulfites']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C, tranches immergées dans la sauce ou dans un peu de bouillon filtré pour éviter le dessèchement. Réchauffer à feu doux sans ébullition, en allongeant d''une louche de bouillon : n''étant retenue par aucun amidon, cette sauce se resserre franchement au froid. La congélation est possible 2 mois pour la viande et sa sauce ensemble, et le dégel lui réussit mieux qu''à la version au roux, une réduction ne se déphasant pas. Ne jamais congeler les cornichons, à ajouter au dernier moment.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-013'), '{"variant_label":"Version tomatée du Sud : doubler le concentré de tomate, ajouter une pointe de piment et servir la sauce plus courte, sans roux.","rationale":"Sans farine, la sauce n''est plus liée mais réduite : il faut trente à quarante minutes d''évaporation pour obtenir la nappe que le roux donnait en vingt, et le rendement final est nettement moindre. Le concentré doublé et le piment déplacent le plat du côté méridional, la tomate prenant la place que tenait l''amidon. On y gagne une sauce plus franche et moins pâteuse, on y perd du volume et un peu de la douceur qui tempérait le vinaigre.","operations":[{"op":"scale","form":"Concentré de tomate","factor":2},{"op":"add","form":"Piment de Cayenne","quantity":1,"unit":"g","role":"épice"},{"op":"remove","form":"Farine de blé T55"}],"steps":[{"op":"replace","n":7,"instruction":"Incorporer le concentré de tomate aux échalotes réduites et le laisser pincer deux à trois minutes à feu doux, en remuant sans arrêt jusqu''à ce qu''il fonce et perde son goût de conserve. Ajouter le piment de Cayenne, puis verser le bouillon filtré louche après louche et laisser réduire à découvert trente à quarante minutes : rien ne lie cette sauce que sa propre évaporation, et elle est prête quand elle nappe le dos de la cuillère sans couler."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
