  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Immerger les œufs dans une casserole d''eau frémissante et compter dix minutes à petits bouillons, puis les refroidir sous l''eau courante, les écaler et les couper en rondelles régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réunir la tomate râpée dans un saladier avec le vinaigre de vin rouge, les deux tiers de l''huile d''olive, le sel fin et le poivre noir moulu ; laisser macérer un quart d''heure le temps que le jus se colore et se parfume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre le pain de campagne en deux dans l''épaisseur et creuser légèrement la mie de la partie supérieure pour ménager de la place à la garniture et à l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Frotter énergiquement les deux faces internes avec la gousse d''ail fendue en deux, côté tranché contre la mie, jusqu''à ce qu''il n''en reste presque rien : c''est la mie sèche qui râpe l''ail, et non l''inverse. Badigeonner ensuite de l''huile d''olive restante, puis arroser du jus rendu par la tomate jusqu''à ce que la mie soit franchement humide sans être détrempée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Étaler la tomate râpée égouttée sur la base, répartir dessus les rondelles d''œuf dur et parsemer d''olives noires dénoyautées et grossièrement concassées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Recoiffer avec la partie supérieure, presser fermement de la paume, envelopper serré dans un papier et laisser reposer trente à soixante minutes au frais avant de découper en quatre parts.');

  INSERT INTO quality.review_tasks
