  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Immerger les œufs dans une casserole d''eau frémissante et compter dix minutes à petits bouillons, puis les refroidir sous l''eau courante, les écaler et les couper en rondelles régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper les tomates en rondelles de trois millimètres et les ranger à plat dans un saladier avec le vinaigre de vin rouge, les deux tiers de l''huile d''olive, le sel fin et le poivre noir moulu ; laisser dégorger un quart d''heure, le temps que le sel tire l''eau de la chair et que la marinade se colore.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre le pain de campagne en deux dans l''épaisseur et creuser légèrement la mie de la partie supérieure pour ménager de la place à la garniture et à l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Badigeonner les deux faces internes avec l''huile d''olive restante, puis les arroser de la marinade recueillie au fond du saladier. Elle est bien moins abondante que le jus d''une pulpe râpée : verser en trois fois, en laissant la mie boire entre chaque passage, sinon le pain reste sec d''un côté et détrempé de l''autre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ranger les rondelles de tomate égouttées sur la base en les faisant se chevaucher comme des tuiles, sur deux couches régulières si nécessaire : quatre cent quatre-vingts grammes de tomate ne tiennent pas à plat sur une demi-miche, et une garniture d''épaisseur constante vaut mieux qu''un tas au centre. Répartir dessus les rondelles d''œuf dur et parsemer d''olives noires dénoyautées et grossièrement concassées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Recoiffer avec la partie supérieure, presser fermement de la paume, envelopper serré dans un papier et laisser reposer trente à soixante minutes au frais avant de découper en quatre parts.');

