  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('747e123350d8e5e5c825994c4593bbc3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":3},"dominant_flavors":["tomate mûre","huile d''olive fruitée","olive noire","acidité vinaigrée"],"aroma_families":["fruité olive","végétal frais","acidulé vinaigré"],"target_textures":["mie imbibée et moelleuse","croûte souple","jaune d''œuf crémeux"],"signature_ingredients":["Pain de campagne","Huile d''olive vierge extra","Tomate fraîche mûre","Olive noire"],"identity_guardrails":["La mie doit être imbibée d''huile d''olive et du jus de tomate : un pan bagnat sec n''est plus un pan bagnat.","Tout est assemblé à froid et rien n''est cuit dans le sandwich ; le pain ne passe jamais au grill ni au four.","Aucun beurre ni sauce émulsionnée type mayonnaise : l''huile d''olive vierge extra est l''unique corps gras.","Le repos sous pression fait partie de la recette, il ne s''agit pas d''un sandwich servi à la minute."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
