  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pâtes au thon à l''huile d''olive crue', 'pates au thon a l huile d olive crue', 'France', 'France',
     'meal', 'plat de pâtes', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pâtes au thon à l''huile d''olive crue', 'Petites pâtes avec thon en conserve dans une sauce tomate finie à l''huile d''olive crue', ds.id, 'SRC-018-D3',
    'Myko', 'editorial', 4, 10, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', '2e8a693cd81845d0a7332f269d701cb8',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['tomate cuite','iodé','aillé']::text[],
    ARRAY['aillé','fruité vert','tomate confite']::text[], ARRAY['pâtes al dente','sauce nappante','miettes de poisson fondantes']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Tomate concassée en conserve','Petites pâtes sèches']::text[], ARRAY['Le thon doit être ajouté en fin de cuisson et rester en miettes visibles : émietté trop tôt ou remué jusqu''à disparaître, le plat devient une simple sauce tomate.','La tomate concassée doit réduire avant l''arrivée du poisson : une sauce non réduite délave le plat.','La moitié de l''huile d''olive vierge extra reste crue et n''arrive qu''au dressage : chauffée, elle perd le fruité qui remplace ici les aromates.','Aucun aromate séché n''entre dans la sauce : l''ail et l''huile crue portent seuls le parfum.']::text[],
    ARRAY['mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','poisson']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique ; réchauffer à la poêle avec une cuillère d''eau, jamais à ébullition sous peine de dessécher le thon. La congélation est déconseillée pour le plat assemblé (les pâtes deviennent farineuses), mais la sauce tomate au thon seule se congèle jusqu''à 2 mois.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-018'), '{"variant_label":"Version sans herbes séchées : omettre les herbes de Provence et compter uniquement sur l''ail et l''huile d''olive crue ajoutée au dressage.","rationale":"Le mélange séché sort du plat et rien ne le remplace : il ne reste que l''ail fondu au départ et l''huile versée crue à la fin pour tenir le parfum. La moitié de l''huile est donc réservée au dressage au lieu du quart, ce qui lui laisse son amertume poivrée et son fruité, détruits dès qu''elle chauffe. La sauce y gagne en franchise et sent davantage la tomate et le poisson, elle perd la couche aromatique un peu couvrante que le thym et le romarin séchés apportaient.","operations":[{"op":"remove","form":"Herbes de Provence séchées"}],"steps":[{"op":"replace","n":2,"instruction":"Faire tiédir la moitié de l''huile d''olive dans une sauteuse large, y laisser fondre l''oignon à feu doux jusqu''à ce qu''il devienne translucide sans prendre couleur, puis ajouter l''ail écrasé pour la dernière minute seulement, le temps qu''il libère son parfum. Réserver l''autre moitié de l''huile : c''est elle qui assaisonnera le plat au dressage, et elle ne doit pas voir le feu."},{"op":"replace","n":5,"instruction":"Baisser le feu sous la sauce et y disperser les miettes de thon, puis laisser confire cinq minutes sans remuer trop fort : le poisson doit se réchauffer et prendre le goût de la tomate en restant en morceaux. Rien d''autre ne vient parfumer la sauteuse à ce stade, c''est l''ail fondu du début qui doit s''entendre sous la tomate."},{"op":"replace","n":6,"instruction":"Réunir les pâtes égouttées et la sauce dans la sauteuse, verser l''huile d''olive réservée bien crue et un filet d''eau de cuisson si l''ensemble paraît sec, mélanger hors du feu pour enrober chaque pâte. Une huile qui n''a pas chauffé garde son amertume poivrée et son fruité vert, et c''est tout l''assaisonnement du plat : rectifier sel et poivre, puis servir sans attendre."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
