  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rincer les olives vertes dénoyautées sous l''eau froide et les éponger : leur saumure lactique est bien plus vive que celle de l''olive noire, et la compotée, que les anchois écrasés salent déjà largement, n''a aucune marge pour en recevoir davantage. Répartir ensuite la compotée d''oignons en couche régulière jusqu''au bourrelet, croiser dessus les filets d''anchois réservés de façon à dessiner des losanges, et déposer une olive au creux de chaque losange.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner environ 20 minutes, jusqu''à ce que le pourtour soit doré et le dessous de la pâte sec et ferme au toucher. Sortir la plaque, laisser reposer une dizaine de minutes et servir tiède ou à température ambiante, jamais brûlante.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-019-D2', 'recipe_family', 'Pissaladière aux olives vertes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-019-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-019-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-019-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('24579698233731354e391fd826cf9a4e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["oignon confit sucré","anchois salé","olive noire","huile d''olive"],"aroma_families":["allium","herbacé","marin"],"target_textures":["oignon fondant","croûte croustillante","filet d''anchois moelleux"],"signature_ingredients":["Oignon jaune cru","Anchois à l''huile, égoutté","Olive verte dénoyautée"],"identity_guardrails":["Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.","Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.","Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.","La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pissaladière au fenouil', 'pissaladiere au fenouil', 'France', 'France',
     'meal', 'tarte salée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pissaladière au fenouil', 'Tarte levée aux oignons confits et anchois, avec une couche de fenouil braisé', ds.id, 'SRC-019-D3',
    'Myko', 'editorial', 4, 30, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', 'aa87a317c73a2fdae926dce90cfca15a',
    '{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['oignon confit sucré','anchois salé','olive noire','huile d''olive']::text[],
    ARRAY['allium','herbacé','marin']::text[], ARRAY['oignon fondant','croûte croustillante','filet d''anchois moelleux']::text[],
    ARRAY['Oignon jaune cru','Anchois à l''huile, égoutté','Olive noire']::text[], ARRAY['Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.','Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.','Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.','La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée.']::text[],
    ARRAY['mijotage','rôtissage','pétrissage']::text[], ARRAY[]::text[], ARRAY['gluten','poisson']::text[],
    'Se conserve 48 h au réfrigérateur entre 0 et 4 °C, couverte d''un film ou en boîte hermétique ; se déguste tiède ou froide, et se retend en 8 minutes à 180 °C. La compotée d''oignons seule se congèle très bien 3 mois, mais la tarte montée supporte mal la congélation : la pâte ressort détrempée.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-019'), '{"variant_label":"Pissaladière au fenouil : remplacer un tiers des oignons par du fenouil émincé compoté avec eux.","rationale":"Un tiers des oignons cède la place à du fenouil émincé, soit deux cent soixante-dix-sept grammes de bulbe contre autant d''oignon en moins. La compotée perd un peu de son sucre et gagne un fond anisé qui tient tête à l''anchois au lieu de l''envelopper. Le fenouil demande cinq minutes de plus pour céder complètement, et ses côtes extérieures, si on ne les écarte pas, laissent des fils désagréables dans une garniture qu''on attend fondante.","operations":[{"op":"scale","form":"Oignon jaune cru","factor":0.6667},{"op":"add","form":"Fenouil frais","quantity":277,"unit":"g","role":"légume","optional":false}],"steps":[{"op":"replace","n":2,"instruction":"Peler les oignons et les tailler en lamelles fines et régulières. Parer les bulbes de fenouil, ôter la base dure et les côtes extérieures les plus filandreuses, puis les émincer à la même finesse pour que les deux légumes fondent au même rythme. Chauffer le reste de l''huile d''olive dans une grande sauteuse, y verser ensemble oignons et fenouil avec le sucre semoule, le thym séché, les herbes de Provence et le poivre noir moulu."},{"op":"replace","n":3,"instruction":"Couvrir et laisser compoter sur feu très doux une quarantaine de minutes en remuant toutes les cinq minutes ; ajouter l''ail écrasé à mi-cuisson. Le fenouil met plus longtemps que l''oignon à céder : la compotée n''est prête que lorsque ses lamelles s''écrasent sans résistance entre deux doigts, translucides et à peine blondes, sans jamais colorer ni accrocher — une cuillère d''eau suffit à rattraper le fond si besoin. Ne pas saler à cette étape."},{"op":"replace","n":6,"instruction":"Répartir la compotée d''oignons et de fenouil en couche régulière jusqu''au bourrelet, croiser dessus les filets d''anchois réservés de façon à dessiner des losanges, et déposer une olive noire au creux de chaque losange."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
