    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-019-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-019-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-019-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('aa87a317c73a2fdae926dce90cfca15a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["oignon confit sucré","anchois salé","olive noire","huile d''olive"],"aroma_families":["allium","herbacé","marin"],"target_textures":["oignon fondant","croûte croustillante","filet d''anchois moelleux"],"signature_ingredients":["Oignon jaune cru","Anchois à l''huile, égoutté","Olive noire"],"identity_guardrails":["Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.","Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.","Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.","La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pissaladière à l''aubergine rôtie', 'pissaladiere a l aubergine rotie', 'France', 'France',
     'meal', 'tarte salée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pissaladière à l''aubergine rôtie', 'Tarte niçoise levée aux oignons confits, anchois, olives et tranches d''aubergine rôtie', ds.id, 'SRC-019-D4',
    'Myko', 'editorial', 4, 35, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a313a487b84408531a0e7505e08cd785',
    '{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['oignon confit sucré','anchois salé','olive noire','huile d''olive']::text[],
    ARRAY['allium','herbacé','marin']::text[], ARRAY['oignon fondant','croûte croustillante','filet d''anchois moelleux']::text[],
    ARRAY['Oignon jaune cru','Anchois à l''huile, égoutté','Olive noire']::text[], ARRAY['Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.','Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.','Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.','La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée.']::text[],
    ARRAY['mijotage','rôtissage','pétrissage']::text[], ARRAY[]::text[], ARRAY['gluten','poisson']::text[],
    'Se conserve 48 h au réfrigérateur entre 0 et 4 °C, couverte d''un film ou en boîte hermétique ; se déguste tiède ou froide, et se retend en 8 minutes à 180 °C. La compotée d''oignons seule se congèle très bien 3 mois, mais la tarte montée supporte mal la congélation : la pâte ressort détrempée.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-019'), '{"variant_label":"Base à l''aubergine rôtie écrasée mêlée aux oignons, pour une garniture plus fondante.","rationale":"Six cent cinquante grammes d''aubergine rôtie au four viennent s''écraser dans une compotée d''oignons réduite d''un tiers. La garniture passe de la lamelle fondante à la purée grumeleuse : elle couvre mieux la pâte, tient à la découpe et porte un goût de fumé léger que l''oignon seul ne donne pas. Le prix à payer est un four occupé quarante minutes en amont et une garniture plus lourde en eau, qu''il faut vraiment laisser sécher avant de l''étaler.","operations":[{"op":"scale","form":"Oignon jaune cru","factor":0.65},{"op":"add","form":"Aubergine fraîche","quantity":650,"unit":"g","role":"légume","optional":false}],"steps":[{"op":"replace","n":5,"instruction":"Monter le four à 220 °C. Étaler la pâte au rouleau en un rectangle d''environ 40 × 25 cm sur une plaque tapissée de papier cuisson, en laissant un léger bourrelet tout autour pour retenir la garniture."},{"op":"replace","n":6,"instruction":"Répartir la garniture d''oignons et d''aubergine en couche régulière jusqu''au bourrelet, croiser dessus les filets d''anchois réservés de façon à dessiner des losanges, et déposer une olive noire au creux de chaque losange."},{"op":"insert","after":3,"instruction":"Prélever à la cuillère la chair des aubergines rôties en laissant la peau et le jus brun qui s''est amassé sous elles, l''écraser grossièrement à la fourchette et la mêler hors du feu aux oignons compotés. Garder du grain : une chair mixée trop lisse coulerait sur la pâte au lieu d''y tenir en couche."},{"op":"insert","after":1,"instruction":"Chauffer le four à 200 °C. Fendre les aubergines en deux dans la longueur, quadriller la chair à la pointe du couteau sans entamer la peau, puis les coucher face tranchée contre une plaque tapissée de papier cuisson. Les rôtir quarante minutes pendant que les oignons compotent : la peau doit se rider et se creuser, et la chair s''enfoncer sans la moindre résistance."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
