  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Ôter des poireaux les feuilles vertes les plus coriaces et l''extrémité racinaire, fendre les blancs sur toute leur longueur, puis les passer sous un filet d''eau froide en écartant les épaisseurs pour déloger la terre. Détailler ensuite en tronçons d''environ trois centimètres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter un grand volume d''eau salée à frémissement, y plonger les tronçons et compter une quinzaine de minutes de cuisson : la lame d''un couteau doit s''enfoncer sans buter dans le cœur du poireau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le contenu de la casserole dans une passoire et appuyer franchement sur les poireaux avec le dos d''une louche pour en chasser le plus d''eau possible. C''est ce pressage qui évite au gratin de rendre du jus en cuisant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire chauffer l''huile d''olive vierge extra dans une sauteuse large et y remuer les poireaux égouttés trois à quatre minutes sur feu vif, le temps que l''humidité restante s''évapore et que les tronçons prennent une légère coloration. Saler et poivrer à ce moment-là.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la sauteuse du feu, arroser de crème fraîche liquide entière et mélanger doucement jusqu''à ce que chaque tronçon soit enrobé d''un voile crémeux. Goûter et rectifier le sel et le poivre avant de dresser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la préparation dans un plat à gratin en une couche régulière, sans tasser, recouvrir uniformément de gruyère râpé jusqu''aux bords, puis parsemer par-dessus la chapelure de blé en pluie fine. La répartir du bout des doigts sans laisser d''amas : un tas de mie reste farineux au cœur là où un voile grille de part en part.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 210 °C sur la grille haute pendant quinze à vingt minutes, jusqu''à ce que la chapelure prenne une couleur de croûte de pain et que le fromage bouillonne dessous. La mie sèche brunit bien avant le gruyère : ne plus quitter le four sur les trois dernières minutes. Laisser reposer cinq minutes avant de servir à même le plat de cuisson, le temps que la croûte se raffermisse.');

