$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poireaux vapeur gratinés au gruyère', 'poireaux vapeur gratines au gruyere', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poireaux vapeur gratinés au gruyère', 'Poireaux cuits à la vapeur puis gratinés dans une crème fraîche au gruyère', ds.id, 'SRC-020-D4',
    'Myko', 'editorial', 4, 25, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'be7b14474883d5b58c626eaa9a98aac8',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['poireau doux','crème lactée','fromage gratiné']::text[],
    ARRAY['lactée','alliacée','grillée']::text[], ARRAY['fondant','croûte gratinée','nappage crémeux']::text[],
    ARRAY['Poireau cru','Gruyère râpé','Crème fraîche liquide entière']::text[], ARRAY['Le poireau doit être précuit puis pressé : sans cet égouttage, le plat rend son eau et devient une soupe gratinée.','Sans gruyère râpé sur le dessus, il n''y a plus de croûte dorée et le plat cesse d''être un gratin.','Le liant blanc et onctueux est obligatoire : privé de crème, l''appareil n''est plus qu''un plat de poireaux rôtis.']::text[],
    ARRAY['cuisson vapeur','gratinage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, couvert une fois complètement refroidi, et se réchauffe 15 minutes à 180 °C pour retrouver la croûte. La congélation est déconseillée : le poireau relâche son eau à la décongélation et la crème risque de trancher.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-020'), '{"variant_label":"Cuisson vapeur : passer les tronçons cinq minutes au panier vapeur au lieu de l''eau bouillante, pour un poireau moins gorgé d''eau.","rationale":"Les tronçons passent cinq minutes au panier vapeur au lieu d''un quart d''heure dans l''eau bouillante. Le poireau n''est plus lessivé : il garde son vert, son goût et sa tenue, et le pressage à la louche devient inutile puisqu''il n''a rien bu. La cuisson totale tombe d''une dizaine de minutes. En contrepartie la vapeur pardonne moins — cinq minutes de trop et les tronçons se défont en filaments au moment de les remuer dans la sauteuse.","operations":[],"steps":[{"op":"replace","n":2,"instruction":"Disposer les tronçons en une seule couche dans un panier vapeur posé sur une eau à gros bouillons, couvrir et compter cinq minutes montre en main. La lame doit entrer sans buter tout en rencontrant encore un peu de matière : la vapeur cuit sans dissoudre, le poireau en sort vert et ferme au lieu de gris et flasque."},{"op":"replace","n":3,"instruction":"Sortir le panier et laisser les tronçons s''égoutter deux minutes sans jamais les presser. Ils n''ont pas bu d''eau, il n''y a donc rien à chasser, et le dos de la louche ne ferait ici que les écraser et les défaire."},{"op":"replace","n":4,"instruction":"Faire chauffer l''huile d''olive vierge extra dans une sauteuse large et y remuer les poireaux deux minutes seulement sur feu vif, le temps de sécher leur surface et de leur donner une pointe de coloration. Les retourner à la spatule plutôt qu''à la cuillère, ils sont encore entiers et le resteront. Saler et poivrer à ce moment-là."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

