  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mettre le four à chauffer sur 200 °C. Trancher une calotte au sommet de chaque poivron du côté du pédoncule et la garder de côté : elle servira de chapeau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Creuser l''intérieur des poivrons pour enlever les pépins et les nervures pâles, en veillant à ne pas percer la paroi. Rincer la cavité et l''éponger.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Immerger les poivrons évidés dans une grande casserole d''eau salée à petits bouillons pendant environ quinze minutes : la chair doit céder sous le doigt tout en gardant assez de tenue pour rester debout. Les rafraîchir aussitôt à l''eau froide, puis les laisser s''égoutter retournés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans cette même eau, jeter le riz et l''arrêter à la moitié du temps indiqué sur l''emballage. L''égoutter et l''étaler pour qu''il tiédisse : il absorbera le reste de son eau pendant la cuisson au four.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire fondre les lardons à sec dans une poêle chaude, juste le temps que leur gras devienne translucide, sans chercher de coloration marquée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser un tiers de l''huile d''olive dans la poêle, ajouter l''oignon finement émincé et l''ail écrasé, et laisser suer à feu moyen jusqu''à transparence.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Incorporer la tomate râpée et laisser réduire une dizaine de minutes à découvert, en remuant de temps en temps, jusqu''à ce que le mélange ne rende plus d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hors du feu, réunir dans un saladier le riz à mi-cuisson, la préparation lardons-tomate et les herbes ciselées. Saler, poivrer, puis lier avec l''œuf battu en travaillant la farce à la main pour la rendre homogène.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Remplir les poivrons sans tasser la garniture, recoiffer chacun de sa calotte et les caler debout dans un plat à four badigeonné du reste d''huile d''olive.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Délayer le bouillon de volaille dans un grand verre d''eau chaude et le verser au fond du plat, sans arroser les chapeaux. Ne rien couvrir : c''est tout le principe de cette version, et c''est aussi ce qui fait s''évaporer le fond deux fois plus vite qu''à l''ordinaire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 11, 'Enfourner quarante minutes à découvert, en regardant le fond du plat toutes les dix minutes : dès qu''il n''y reste plus de liquide, rajouter un demi-verre d''eau chaude, sans quoi les sucs attachés brûlent et communiquent leur amertume à toute la farce. La peau se ride et se marque de taches brunes, tandis que la farce, protégée par sa calotte, se resserre sans se dessécher en surface. Laisser reposer dix minutes hors du four avant de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-021-D3', 'recipe_family', 'Poivrons farcis rôtis à découvert',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-021-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-021-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-021-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9d9c80f2f4f0501f922024e8c98263ce'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["poivron rôti","lard fumé","tomate cuite","ail doux"],"aroma_families":["végétal grillé","fumé","aillé","herbacé"],"target_textures":["poivron fondant","riz moelleux","farce liée","surface légèrement grillée"],"signature_ingredients":["Poivron rouge frais","Riz cru","Lardon fumé cru"],"identity_guardrails":["Le poivron entier évidé sert de contenant et cuit avec la farce : farcir un autre légume ou servir la garniture à part change le plat.","Le riz est engagé à mi-cuisson et finit de gonfler au four dans les sucs du poivron ; un riz déjà cuit à cœur donne une farce pâteuse qui n''est plus la recette.","La cuisson se termine au four, pas à la casserole : le poivron doit s''affaisser et caraméliser en surface."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
