DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Potage Parmentier végétarien', 'potage parmentier vegetarien', 'France', 'France',
     'meal', 'soupe', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Potage Parmentier végétarien', 'Soupe de poireau et pomme de terre à l''eau, liée à la crème, sans bouillon de viande', ds.id, 'SRC-022-D3',
    'Myko', 'editorial', 4, 15, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '78a02f42e03add0a35f12c497ee55bd3',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2}'::jsonb, ARRAY['poireau fondu','pomme de terre douce','crème lactée','bouillon de volaille']::text[],
    ARRAY['allium doux','lacté','bouillon de volaille','beurre noisette']::text[], ARRAY['velouté lisse','nappant','sans fibre']::text[],
    ARRAY['Poireau cru','Pomme de terre cuite','Crème fraîche liquide entière']::text[], ARRAY['Le couple poireau + pomme de terre est le plat lui-même : sans l''un des deux, ce n''est plus un potage parmentier.','Les poireaux doivent suer sans coloration ; toute caraméliisation ou saisie brune fait basculer le potage vers une soupe rustique étrangère à l''identité du plat.','La texture doit rester un velouté entièrement mixé : laisser des morceaux entiers en ferait une soupe paysanne, pas un potage.','La crème s''ajoute hors du feu en fin de cuisson, jamais en début de mijotage.']::text[],
    ARRAY['suage','mijotage','mixage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans un contenant fermé ; réchauffer doucement sans faire bouillir pour éviter que la crème ne tranche. Pour la congélation, congeler la base mixée sans crème jusqu''à trois mois et n''incorporer la crème qu''au réchauffage : congelée crémée, elle se déphase et rend le velouté granuleux.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-022'), '{"variant_label":"Remplacer le bouillon de volaille par de l''eau salée pour une version maigre plus végétale, comme le fait la trame chefsimon.","rationale":"L''eau salée remplace au gramme près le bouillon de volaille, ce qui retire du potage sa seule composante carnée et le rend accessible à une table végétarienne. Le goût se resserre sur ce qu''apportent réellement le poireau et la pomme de terre : plus végétal, plus net, mais aussi plus court, sans le fond salé qui portait l''ensemble. Le sel passe de six à dix grammes et cesse d''être facultatif, car plus rien d''autre n''assaisonne le mouillement. La cuisson doit rester au frémissement : c''est l''amidon de la pomme de terre qui fait ici toute la liaison.","operations":[{"op":"substitute","form":"Bouillon de volaille","with":"Eau","quantity":750,"unit":"g","role":"mouillement"},{"op":"set","form":"Sel fin","quantity":10,"role":"assaisonnement","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Égoutter les cubes de pomme de terre, les mêler aux poireaux fondus, mouiller d''eau bien chaude jusqu''à recouvrir les légumes, puis saler d''emblée et sans timidité — rien d''autre n''apportera de fond à ce potage, et un mouillement fade ne se rattrape pas au moment de servir. Amener au frémissement."},{"op":"replace","n":5,"instruction":"Couvrir et maintenir un frémissement doux vingt-cinq à trente minutes : la pointe d''un couteau doit traverser un cube de pomme de terre sans la moindre résistance. Tenir la casserole en dessous de l''ébullition franche, qui disperserait l''amidon dans le liquide alors que c''est précisément lui qui doit lier ce velouté maigre."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
