    VALUES
      ('content', to_jsonb('6e7a0c974a6fb9e934ce7429929a4f44'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2},"dominant_flavors":["poireau fondu","pomme de terre douce","crème lactée","bouillon de volaille"],"aroma_families":["allium doux","lacté","bouillon de volaille","beurre noisette"],"target_textures":["velouté lisse","nappant","sans fibre"],"signature_ingredients":["Poireau cru","Pomme de terre cuite","Crème fraîche liquide entière"],"identity_guardrails":["Le couple poireau + pomme de terre est le plat lui-même : sans l''un des deux, ce n''est plus un potage parmentier.","Les poireaux doivent suer sans coloration ; toute caraméliisation ou saisie brune fait basculer le potage vers une soupe rustique étrangère à l''identité du plat.","La texture doit rester un velouté entièrement mixé : laisser des morceaux entiers en ferait une soupe paysanne, pas un potage.","La crème s''ajoute hors du feu en fin de cuisson, jamais en début de mijotage."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Riz cantonais aux crevettes', 'riz cantonais aux crevettes', 'France', 'France',
     'meal', 'plat sauté', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Riz cantonais aux crevettes', 'Riz sauté avec crevettes décortiquées, œufs brouillés, petits pois et oignons', ds.id, 'SRC-023-D1',
    'Myko', 'editorial', 4, 15, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', 'fab856a5f30b4ac441e4b7872def092f',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2}'::jsonb, ARRAY['salé','umami','douceur végétale']::text[],
    ARRAY['alliacé','grillé','céréalier']::text[], ARRAY['grains détachés','moelleux','lanières fondantes']::text[],
    ARRAY['Riz cru','Œuf cru','Crevette crue décortiquée','Petit pois surgelé']::text[], ARRAY['L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.','Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.','Le trio riz, œuf et petit pois est présent dans les sept sources du dossier : retirer l''un des trois fait sortir de l''identité du riz cantonais.','Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce.']::text[],
    ARRAY['saisie','blanchiment']::text[], ARRAY[]::text[], ARRAY['œuf','lait','gluten','soja','sésame','crustacés']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, à refroidir rapidement après cuisson car le riz cuit tiède est un terrain favorable à Bacillus cereus. Réchauffer à la poêle bien chaude, jamais tiède. La congélation est possible 1 mois mais dégrade nettement la texture : les petits pois rendent de l''eau et l''omelette devient caoutchouteuse — décongeler au réfrigérateur puis sauter à feu vif.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-023'), '{"variant_label":"Version aux crevettes : remplacer tout ou partie du jambon blanc par des crevettes décortiquées jetées trente secondes dans le wok très chaud avant les légumes.","rationale":"Les crevettes crues prennent la place du jambon : saisies très vite puis réservées, elles apportent une chair douce et iodée là où la charcuterie donnait un salé franc. Rien dans la liste ne remplace ce sel — il se rattrape au goût en fin de sauté, à la sauce soja ou au sel fin —, et le riz gagne en échange un jus léger que les grains boivent au dernier moment. La marge de manœuvre se réduit : une crevette laissée une minute de trop durcit et rend son eau dans le riz, qui cesse alors d''être en grains détachés.","operations":[{"op":"substitute","form":"Jambon blanc cuit","with":"Crevette crue décortiquée","quantity":160,"unit":"g","role":"protéine"}],"steps":[{"op":"replace","n":3,"instruction":"Pendant ce temps, ébouillanter les petits pois deux minutes puis les égoutter et les rafraîchir sous l''eau froide. Tailler l''oignon en petits dés, hacher l''ail au couteau et débiter la carotte en brunoise fine. Éponger les crevettes décortiquées une à une dans un linge propre : mouillées, elles bouillent au lieu de saisir et ne prennent aucune couleur."},{"op":"replace","n":5,"instruction":"Remettre le wok sur le feu vif et jeter dans l''huile restée au fond l''oignon, l''ail et la carotte. Les remuer sans arrêt deux à trois minutes : ils doivent s''assouplir en gardant leur teinte claire, sans jamais roussir."},{"op":"replace","n":6,"instruction":"Ajouter les petits pois et sauter une minute pour les enrober de matière grasse, puis verser le riz refroidi en l''écrasant du dos de la spatule pour séparer les paquets de grains. Étaler le tout contre les parois chaudes et laisser accrocher quelques secondes entre deux mouvements."},{"op":"replace","n":7,"instruction":"Remettre les crevettes et le jus qu''elles ont rendu dans l''assiette, disperser les lanières d''omelette, arroser de sauce soja versée en pluie sur le bord brûlant du wok, ajouter l''huile de sésame hors du feu, goûter puis rectifier en sel et en poivre. Sauter une dernière minute, le temps de réchauffer les crevettes sans les recuire, et envoyer immédiatement."},{"op":"insert","after":4,"instruction":"Faire fumer l''huile d''olive dans un wok ou une grande sauteuse et y jeter les crevettes en une seule couche. Les laisser trente secondes sans y toucher, le temps qu''elles rosissent et se rétractent, les retourner d''un coup de spatule puis les débarrasser aussitôt dans une assiette : leur cuisson s''achèvera à la chaleur du riz."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

