  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5a9124f8a64fbf60a4e469e74bb5433a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2},"dominant_flavors":["salé","umami","douceur végétale"],"aroma_families":["alliacé","grillé","céréalier"],"target_textures":["grains détachés","moelleux","lanières fondantes"],"signature_ingredients":["Riz cru","Œuf cru","Petit pois surgelé"],"identity_guardrails":["L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.","Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.","Le trio riz, œuf et petit pois est présent dans les sept sources du dossier : retirer l''un des trois fait sortir de l''identité du riz cantonais.","Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
