  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Riz cantonais aux lardons fumés', 'Riz sauté avec œufs brouillés, lardons fumés et petits pois', ds.id, 'SRC-023-D3',
    'Myko', 'editorial', 4, 15, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ecd2abdf0886a40516fd1c2baee910cc',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['salé','umami','fumé']::text[],
    ARRAY['fumé','alliacé','grillé','céréalier']::text[], ARRAY['grains détachés','lardons dorés','lanières fondantes']::text[],
    ARRAY['Riz cru','Œuf cru','Lardon fumé cru','Petit pois surgelé']::text[], ARRAY['L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.','Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.','Les lardons partent dans un wok froid et fondent avant l''huile : jetés dans une matière grasse déjà brûlante, ils saisissent sans rien rendre et le riz n''est jamais fumé.','Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce.']::text[],
    ARRAY['saisie','blanchiment','rendu de graisse']::text[], ARRAY[]::text[], ARRAY['œuf','lait','gluten','soja','sésame']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, à refroidir rapidement après cuisson car le riz cuit tiède est un terrain favorable à Bacillus cereus. Réchauffer à la poêle bien chaude, jamais tiède. La congélation est possible 1 mois mais dégrade nettement la texture : les petits pois rendent de l''eau et l''omelette devient caoutchouteuse — décongeler au réfrigérateur puis sauter à feu vif.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-023'), '{"variant_label":"Version aux lardons, courante chez marmiton.org : substituer des lardons fumés au jambon blanc et les faire rendre leur gras avant d''ajouter l''huile.","rationale":"Les lardons remplacent le jambon et démarrent seuls dans le wok froid, où ils fondent avant que l''huile n''arrive : la matière grasse du sauté devient fumée, et le riz avec elle. L''huile d''olive tombe de moitié puisque le lard en fournit autant, et la sauce soja recule d''un tiers, la charcuterie salant déjà beaucoup. Le plat gagne en profondeur ce qu''il perd en netteté : le fumé couvre la douceur des petits pois et l''œuf passe au second plan.","operations":[{"op":"substitute","form":"Jambon blanc cuit","with":"Lardon fumé cru","quantity":120,"unit":"g","role":"garniture salée"},{"op":"set","form":"Huile d''olive vierge extra","quantity":14,"role":"matière grasse"},{"op":"set","form":"Sauce soja","quantity":40,"role":"assaisonnement"}],"steps":[{"op":"replace","n":3,"instruction":"Pendant ce temps, ébouillanter les petits pois deux minutes puis les égoutter et les rafraîchir sous l''eau froide. Tailler l''oignon en petits dés, hacher l''ail au couteau et débiter la carotte en brunoise fine."},{"op":"replace","n":5,"instruction":"Jeter les lardons fumés dans le wok encore froid et les faire fondre à feu moyen quatre à cinq bonnes minutes, jusqu''à ce qu''ils blondissent et que leur gras coule au fond : démarrés à froid, ils le rendent au lieu de le garder, mais il faut leur laisser ce temps-là. Verser alors le filet d''huile d''olive, monter le feu, ajouter l''oignon, l''ail et la carotte et les remuer sans arrêt deux à trois minutes, sans jamais les laisser roussir."},{"op":"replace","n":6,"instruction":"Ajouter les petits pois et sauter une minute pour les enrober du gras fumé, puis verser le riz refroidi en l''écrasant du dos de la spatule pour séparer les paquets de grains. Étaler le tout contre les parois chaudes et laisser accrocher quelques secondes entre deux mouvements."},{"op":"replace","n":7,"instruction":"Disperser les lanières d''omelette, arroser de sauce soja versée en pluie sur le bord brûlant du wok, mais d''une main plus retenue qu''à l''ordinaire : le lard a déjà salé le riz. Ajouter l''huile de sésame hors du feu, goûter puis rectifier en poivre et en sel seulement si c''est nécessaire. Sauter une dernière minute et envoyer immédiatement, tant que la vapeur monte."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

