  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Passer le riz sous l''eau claire en le brassant à la main jusqu''à ce que l''eau ressorte limpide, puis le mettre dans une casserole avec une fois et demie son volume d''eau salée. Porter à frémissement, couvrir, baisser au minimum et laisser boire tout le liquide sans jamais soulever le couvercle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laisser gonfler dix minutes hors du feu, toujours couvert, puis étaler le riz en couche mince sur un grand plat pour qu''il tiédisse et que les grains cessent de coller entre eux. Un riz refroidi tient le sauté ; un riz brûlant se transforme en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, ébouillanter les petits pois deux minutes puis les égoutter et les rafraîchir sous l''eau froide. Tailler l''oignon en petits dés, hacher l''ail au couteau, débiter la carotte en brunoise fine et couper le jambon en cubes de la taille d''un pois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Fouetter les œufs avec une pincée de sel et un tour de moulin. Faire mousser le beurre dans une poêle à feu doux sans le laisser colorer, y verser les œufs et les travailler sans arrêt à la spatule en ramenant les bords vers le centre : ils doivent prendre en petits caillots brillants. Les débarrasser dans un bol dès qu''ils cessent de couler, la chaleur du riz finira le travail.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire fumer l''huile d''olive dans un wok ou une grande sauteuse, y jeter oignon, ail et carotte, et les remuer sans arrêt deux à trois minutes : ils doivent s''assouplir en gardant leur teinte claire, sans jamais roussir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter le jambon et les petits pois, sauter une minute pour les enrober de matière grasse, puis verser le riz refroidi en l''écrasant du dos de la spatule pour séparer les paquets de grains. Étaler le tout contre les parois chaudes et laisser accrocher quelques secondes entre deux mouvements.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Verser les œufs brouillés sur le riz brûlant et les défaire en gros morceaux d''un geste bref, sans les écraser. Arroser de sauce soja versée en pluie sur le bord du wok, ajouter l''huile de sésame hors du feu, goûter puis rectifier en sel et en poivre. Sauter trente secondes à peine et envoyer immédiatement : au-delà, les œufs rendent leur eau et se raidissent.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-023-D4', 'recipe_family', 'Riz sauté beurré aux œufs brouillés',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-023-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-023-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-023-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5de6b1b156d9f6c9447c7c2accef3b3f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["salé","umami","beurre frais"],"aroma_families":["alliacé","grillé","lacté","céréalier"],"target_textures":["grains détachés","œufs en caillots crémeux","moelleux"],"signature_ingredients":["Riz cru","Œuf cru","Jambon blanc cuit","Petit pois surgelé"],"identity_guardrails":["Les œufs sont brouillés au beurre à part et réincorporés en fin de sauté : versés crus sur le riz, ils l''enroberaient d''une pellicule caillée au lieu de rester en caillots.","Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.","Le trio riz, œuf et petit pois reste intouchable : retirer l''un des trois fait sortir de l''identité du riz sauté cantonais.","Le sauté se fait sur feu vif et court, jamais en mijotage : le beurre arrondit le plat, il ne le transforme pas en riz crémeux."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade de riz niçoise au poivron blanchi', 'salade de riz nicoise au poivron blanchi', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade de riz niçoise au poivron blanchi', 'Riz froid avec thon, œufs, tomates et poivron vert blanchi en vinaigrette', ds.id, 'SRC-024-D1',
    'Myko', 'editorial', 4, 20, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '6fcd9c8ee4f1e6aecdd099cb514a2953',
    '{"sweet":1,"salty":2,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":3,"intensity":2}'::jsonb, ARRAY['tomate','huile d''olive','poivron adouci']::text[],
    ARRAY['végétal','fruité']::text[], ARRAY['grains de riz détachés','dés de poivron tendres et fermes','enrobage huileux léger']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Riz cru','Huile d''olive vierge extra']::text[], ARRAY['Sans thon ni œuf dur, ce n''est plus une salade niçoise mais une salade de riz aux crudités.','Le riz est refroidi avant d''être assaisonné : tiède, il boit l''huile et devient pâteux.','Le poivron n''est qu''ébouillanté une minute puis refroidi net : cuit davantage, il s''affaisse et la salade perd le mordant qui la tient.','Les dés sont épongés avant d''être assaisonnés : l''eau de blanchiment retenue délaverait l''assaisonnement à la tomate.']::text[],
    ARRAY['pochage','blanchiment','marinade','émulsion']::text[], ARRAY[]::text[], ARRAY['poisson','œuf']::text[],
    'Se conserve 24 à 48 heures au réfrigérateur entre 0 et 4 °C dans un contenant hermétique ; sortir le saladier un quart d''heure avant le service pour réveiller le fruité de l''huile, qui fige au froid. Ne supporte pas la congélation : le riz devient farineux et les légumes crus rendent toute leur eau à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-024'), '{"variant_label":"Plonger les dés de poivron vert une minute dans l''eau bouillante puis les refroidir aussitôt, pour une version plus digeste tout en gardant du croquant.","rationale":"Une minute d''eau bouillante casse la crudité du poivron : la peau s''assouplit, l''amertume verte tombe et le légume se digère mieux, ce qui est tout l''objet de la manœuvre. Le refroidissement immédiat lui garde du croquant, mais un croquant moins vif que celui du dé cru — la salade y perd un peu de son mordant. Il faut éponger les dés avant de les mêler, faute de quoi l''eau retenue délaye l''assaisonnement à la tomate.","operations":[],"steps":[{"op":"replace","n":4,"instruction":"Pendant la cuisson du riz, fendre le poivron vert frais, en ôter le pédoncule, les graines et les cloisons blanches, puis le détailler en petits dés réguliers de la taille d''un grain de maïs. Les plonger une minute dans une petite casserole d''eau bouillante, pas davantage, et les verser aussitôt dans un bol d''eau glacée : le passage est assez bref pour n''attendrir que la peau, et le choc froid arrête net une cuisson qui, poursuivie, viderait le dé de sa fermeté. Les égoutter et les éponger soigneusement avant de les mêler à la salade."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
