DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade piémontaise au poulet', 'salade piemontaise au poulet', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade piémontaise au poulet', 'Pommes de terre, blanc de poulet poché, œufs durs et cornichons en mayonnaise moutardée', ds.id, 'SRC-025-D3',
    'Myko', 'editorial', 4, 30, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', '26ae295f8378917f7254b9edd184e742',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['acidulé','salé','moutardé','crémeux']::text[],
    ARRAY['vinaigré','herbacé','végétal frais']::text[], ARRAY['fondant','croquant','crémeux']::text[],
    ARRAY['Pomme de terre cuite','Mayonnaise','Cornichon au vinaigre','Œuf dur']::text[], ARRAY['Sans dés de pomme de terre cuite refroidis, ce n''est plus une salade piémontaise mais une simple salade de crudités.','La sauce doit rester à dominante mayonnaise : remplacée par une vinaigrette seule, le plat perd son onctuosité caractéristique.','L''acidité vive apportée par les cornichons et le vinaigre est constitutive du plat ; sans elle, l''ensemble devient plat et gras.','Le plat se sert froid après repos au réfrigérateur : servi tiède, il n''est pas reconnaissable.']::text[],
    ARRAY['pochage','émulsion']::text[], ARRAY[]::text[], ARRAY['œuf','moutarde','lait','sulfites']::text[],
    'Se conserve 48 heures maximum au réfrigérateur entre 0 et 4 °C, dans un contenant hermétique, en raison de la mayonnaise et de l''œuf dur. Sortir 10 minutes avant de servir. Ne se congèle pas : la mayonnaise se déphase et la pomme de terre devient farineuse et granuleuse à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-025'), '{"variant_label":"Sans porc : substituer au jambon blanc des blancs de volaille cuits taillés en dés, comme le proposent certaines sources du dossier.","rationale":"Le blanc de volaille poché remplace le jambon : la salade quitte le registre de la charcuterie pour une chair neutre, plus maigre et beaucoup moins salée — il faut relever la sauce en conséquence. Le poulet se poche à peine frémissant puis refroidit dans son bouillon, sans quoi il sèche et devient filandreux au contact de la sauce froide. Compter un quart d''heure de pochage mené en même temps que les pommes de terre, et une découpe de plus au moment de l''assemblage.","operations":[{"op":"substitute","form":"Jambon blanc cuit","with":"Blanc de poulet cru, sans peau","quantity":250,"unit":"g","role":"protéine"}],"steps":[{"op":"replace","n":3,"instruction":"Rincer les tomates, retirer le pédoncule, les ouvrir en deux et évacuer graines et jus avec une petite cuillère pour éviter que la salade ne rende de l''eau. Tailler la chair en cubes réguliers, émincer les cornichons en fines rondelles et ciseler finement le persil."},{"op":"replace","n":5,"instruction":"Réunir dans un saladier les dés de pommes de terre, de tomate et de poulet, les rondelles de cornichon et le persil. Verser la sauce, puis remuer à la spatule en soulevant la masse par en dessous, sans écraser, jusqu''à ce que chaque élément soit enrobé. Ajouter les œufs durs en dernier et les mêler d''un geste léger pour garder les morceaux entiers."},{"op":"insert","after":2,"instruction":"Dans une troisième casserole menée en même temps que les pommes de terre, plonger les blancs de poulet dans une eau salée à peine frémissante, jamais bouillante, et compter une quinzaine de minutes selon leur épaisseur : la chair doit être blanche à cœur et céder sous le doigt sans résistance. Les laisser tiédir dans leur eau de cuisson, qui les garde moelleux, puis les égoutter et les tailler en dés d''un centimètre et demi, du même calibre que les pommes de terre."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

