    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 12);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Déposer les pommes de terre entières et non pelées dans un grand volume d''eau salée, porter à petits bouillons et laisser cuire 20 à 25 minutes selon le calibre : la lame d''un couteau doit entrer sans résistance mais la chair rester ferme. Égoutter, passer sous l''eau froide, peler dès que possible et détailler en dés d''environ un centimètre et demi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'En parallèle, plonger les œufs dans une casserole d''eau frémissante et compter 10 minutes pour obtenir des jaunes bien pris. Les transvaser aussitôt dans un bol d''eau glacée : le choc thermique décolle la coquille et facilite l''écalage. Écaler, puis couper chaque œuf en quartiers ou en gros morceaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une troisième casserole menée en même temps que les pommes de terre, plonger les blancs de poulet dans une eau salée à peine frémissante, jamais bouillante, et compter une quinzaine de minutes selon leur épaisseur : la chair doit être blanche à cœur et céder sous le doigt sans résistance. Les laisser tiédir dans leur eau de cuisson, qui les garde moelleux, puis les égoutter et les tailler en dés d''un centimètre et demi, du même calibre que les pommes de terre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Rincer les tomates, retirer le pédoncule, les ouvrir en deux et évacuer graines et jus avec une petite cuillère pour éviter que la salade ne rende de l''eau. Tailler la chair en cubes réguliers, émincer les cornichons en fines rondelles et ciseler finement le persil.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Dans un bol, délayer la moutarde avec le vinaigre, puis incorporer la mayonnaise et la crème fraîche en fouettant jusqu''à obtenir une sauce lisse et nappante. Saler, poivrer, goûter : elle doit paraître franchement relevée, car les pommes de terre en absorberont une bonne part.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Réunir dans un saladier les dés de pommes de terre, de tomate et de poulet, les rondelles de cornichon et le persil. Verser la sauce, puis remuer à la spatule en soulevant la masse par en dessous, sans écraser, jusqu''à ce que chaque élément soit enrobé. Ajouter les œufs durs en dernier et les mêler d''un geste léger pour garder les morceaux entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Filmer le saladier et le placer au réfrigérateur au moins une heure, idéalement deux : ce repos permet à la pomme de terre de s''imprégner de la sauce et de lier l''ensemble. Rectifier le sel, le poivre et l''acidité juste avant de servir, bien frais.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-025-D3', 'recipe_family', 'Salade piémontaise au poulet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-025-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-025-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-025-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('26ae295f8378917f7254b9edd184e742'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["acidulé","salé","moutardé","crémeux"],"aroma_families":["vinaigré","herbacé","végétal frais"],"target_textures":["fondant","croquant","crémeux"],"signature_ingredients":["Pomme de terre cuite","Mayonnaise","Cornichon au vinaigre","Œuf dur"],"identity_guardrails":["Sans dés de pomme de terre cuite refroidis, ce n''est plus une salade piémontaise mais une simple salade de crudités.","La sauce doit rester à dominante mayonnaise : remplacée par une vinaigrette seule, le plat perd son onctuosité caractéristique.","L''acidité vive apportée par les cornichons et le vinaigre est constitutive du plat ; sans elle, l''ensemble devient plat et gras.","Le plat se sert froid après repos au réfrigérateur : servi tiède, il n''est pas reconnaissable."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade piémontaise végétarienne', 'salade piemontaise vegetarienne', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade piémontaise végétarienne', 'Pommes de terre, œufs durs et cornichons liés à la mayonnaise moutardée, sans charcuterie', ds.id, 'SRC-025-D4',
    'Myko', 'editorial', 4, 25, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c9429737b96d0ef4a7e3b715d81b71fe',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['acidulé','salé','moutardé','crémeux']::text[],
    ARRAY['vinaigré','herbacé','végétal frais']::text[], ARRAY['fondant','croquant','crémeux']::text[],
    ARRAY['Pomme de terre cuite','Mayonnaise','Cornichon au vinaigre','Œuf dur']::text[], ARRAY['Sans dés de pomme de terre cuite refroidis, ce n''est plus une salade piémontaise mais une simple salade de crudités.','La sauce doit rester à dominante mayonnaise : remplacée par une vinaigrette seule, le plat perd son onctuosité caractéristique.','L''acidité vive apportée par les cornichons et le vinaigre est constitutive du plat ; sans elle, l''ensemble devient plat et gras.','Le plat se sert froid après repos au réfrigérateur : servi tiède, il n''est pas reconnaissable.']::text[],
    ARRAY['pochage','émulsion']::text[], ARRAY[]::text[], ARRAY['œuf','moutarde','lait','sulfites']::text[],
    'Se conserve 48 heures maximum au réfrigérateur entre 0 et 4 °C, dans un contenant hermétique, en raison de la mayonnaise et de l''œuf dur. Sortir 10 minutes avant de servir. Ne se congèle pas : la mayonnaise se déphase et la pomme de terre devient farineuse et granuleuse à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-025'), '{"variant_label":"Version végétarienne : supprimer le jambon et doubler la part d''œuf dur, en renforçant le croquant avec davantage de cornichons.","rationale":"Sans jambon, l''œuf dur porte seul la protéine : doublé, il passe de garniture à composant principal et rend la salade plus douce, plus jaune, moins salée. Les cornichons renforcés ne rendent pas ce sel, mais leur acidité et leur croquant redonnent une part du relief que la charcuterie tenait. L''ensemble reste crémeux mais perd le contraste salé qui réveillait la pomme de terre : la sauce doit être assaisonnée plus fermement qu''à l''ordinaire.","operations":[{"op":"remove","form":"Jambon blanc cuit"},{"op":"scale","form":"Œuf dur","factor":2},{"op":"set","form":"Cornichon au vinaigre","quantity":130,"role":"condiment"}],"steps":[{"op":"replace","n":3,"instruction":"Rincer les tomates, retirer le pédoncule, les ouvrir en deux et évacuer graines et jus avec une petite cuillère pour éviter que la salade ne rende de l''eau. Tailler la chair en cubes réguliers, puis émincer les cornichons en rondelles un peu épaisses — ils sont plus nombreux ici et doivent croquer sous la dent — et ciseler finement le persil."},{"op":"replace","n":5,"instruction":"Réunir dans un saladier les dés de pommes de terre et de tomate, les rondelles de cornichon et le persil. Verser la sauce et remuer à la spatule en soulevant la masse par en dessous, sans écraser, jusqu''à ce que chaque élément soit enrobé. Ajouter en dernier les œufs durs, deux fois plus abondants qu''à l''ordinaire puisqu''ils portent seuls la protéine du plat, et les mêler d''un geste léger pour garder les morceaux entiers."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
