  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler l''épaule de porc en lanières de la largeur d''un doigt, en tranchant en travers de la fibre : coupée dans le sens des fibres, une viande saisie vite reste filandreuse. Peler et émincer l''oignon jaune en fines lamelles, tailler la carotte en bâtonnets courts.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fumer l''huile d''olive dans un wok ou une grande sauteuse et y jeter la moitié des lanières de porc en une seule couche, sans les tasser. Les laisser une minute sans y toucher, puis les retourner jusqu''à ce qu''elles soient dorées de partout, et les débarrasser dans une assiette avant de recommencer avec le reste : une poêlée surchargée rend son eau et bout au lieu de colorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Remettre le wok vide sur le feu vif, y verser l''oignon et la carotte et les remuer deux à trois minutes seulement : ils doivent s''assouplir et prendre quelques taches dorées en gardant du mordant, loin de la fondue lente que demandait le braisé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les lardons fumés et les laisser crépiter deux minutes en remuant, le temps qu''ils libèrent leur gras et en parfument les légumes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser l''eau et gratter aussitôt le fond à la cuillère en bois pour décoller les sucs caramélisés. Poivrer, puis laisser bouillir vivement deux à trois minutes jusqu''à ce qu''il ne reste qu''un fond de jus sirupeux : le mouillement est ici trois fois plus faible, il sert à déglacer et non à mijoter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le porc et le jus qu''il a rendu dans l''assiette, et le rouler une minute dans ce fond de sauce pour l''enrober et le réchauffer. La viande est déjà cuite : prolongée, elle se contracte et sèche, là où l''épaule braisée gagnait à s''attendrir une heure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
