DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Porc aux pruneaux à la cocotte', 'porc aux pruneaux a la cocotte', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Porc aux pruneaux à la cocotte', 'Épaule de porc mijotée en cocotte avec des pruneaux', ds.id, 'SRC-026-D2',
    'Myko', 'editorial', 4, 20, 90, 'facile',
    NULL, NULL,
    'B', 'candidate', '2fa9ce3063dc4538cc55dc9444c5d33a',
    '{"sweet":3,"salty":2,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['sucré du fruit sec','porc caramélisé','oignon confit']::text[],
    ARRAY['fruit sec','viande rôtie','légume fondu']::text[], ARRAY['viande fondante à la fourchette','pruneau moelleux et gonflé','sauce nappante']::text[],
    ARRAY['Épaule de porc crue','Pruneau dénoyauté']::text[], ARRAY['Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.','La viande doit être saisie en deux fournées et poussée jusqu''au brun : c''est elle seule qui donne au jus la profondeur que la garniture fumée apportait.','La cuisson reste longue et à couvert : un passage rapide à la poêle ne rend pas l''épaule fondante et ne laisse pas les pruneaux parfumer le jus.','Le mouillement se limite à un fond d''eau, pas à un bain : la sauce doit finir réduite et nappante, jamais aqueuse.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['sulfites']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C dans un récipient fermé, et gagne même en goût réchauffé le lendemain à feu doux avec une cuillère d''eau. Le plat se congèle très bien 3 mois : la viande et la sauce supportent la décongélation, les pruneaux ressortent seulement un peu plus fondus.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-026'), '{"variant_label":"Sans lardons : doubler la saisie de la viande pour compenser la profondeur fumée manquante.","rationale":"Retirer les lardons ôte au plat sa colonne fumée et l''essentiel de son sel : la saisie menée en deux fournées et poussée jusqu''au brun redonne du fond au jus, mais ne remplace pas le fumé, qui disparaît vraiment. Il faut désormais saler la cocotte, ce que la recette d''origine n''avait pas à faire, et juger l''assaisonnement une fois le jus réduit. Le résultat est plus maigre, plus franchement porc et pruneau, moins complexe aussi.","operations":[{"op":"remove","form":"Lardon fumé cru"},{"op":"add","form":"Sel fin","quantity":4,"unit":"g","role":"assaisonnement","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Débarrasser l''oignon et la carotte dans une assiette : la saisie se mène ici en deux fournées, et des légumes laissés sur les bords d''une cocotte brûlante noirciraient pendant que la seconde colore, donnant au jus une amertume dont il ne se relève pas. Monter le feu et déposer la moitié des cubes de porc à plat, sans qu''ils se touchent. Les laisser dorer sans les bouger, les retourner face par face jusqu''à ce qu''ils soient colorés partout et presque bruns, les réserver, puis recommencer avec le reste : privée de garniture fumée, la cocotte n''a plus que cette croûte caramélisée pour donner du fond à son jus, et une viande entassée bout au lieu de saisir. Remettre alors dans la cocotte l''oignon, la carotte, toute la viande et les sucs qu''elle a rendus."},{"op":"remove","n":4},{"op":"replace","n":5,"instruction":"Verser l''eau et gratter aussitôt le fond à la cuillère en bois pour décoller les sucs caramélisés. Ajouter le sel fin et poivrer — il n''y a plus de charcuterie pour saler le jus à la place du cuisinier —, porter à petits bouillons puis couvrir et baisser au minimum."},{"op":"replace","n":8,"instruction":"Retirer le couvercle pour les dix dernières minutes et laisser le liquide réduire jusqu''à une sauce brillante qui nappe la cuillère. Mélanger avec précaution, goûter et rectifier en sel et en poivre seulement à ce moment : la réduction concentre l''assaisonnement, et un jus salé trop tôt devient immangeable une fois réduit."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'epaule de porc crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Épaule de porc crue', 530, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pruneau denoyaute' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pruneau dénoyauté', 170, 'g', 'required',
     'fruit sec', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oignon jaune cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oignon jaune cru', 150, 'g', 'required',
     'aromate', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'carotte crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Carotte crue', 120, 'g', 'optional',
     'légume', true, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 30, 'g', 'required',
     'matière grasse', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'eau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Eau', 330, 'ml', 'required',
     'mouillement', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'required',
     'assaisonnement', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler l''épaule de porc en cubes réguliers d''environ quatre centimètres, assez gros pour rester moelleux après une cuisson longue. Peler et émincer finement l''oignon jaune, tailler la carotte en petits dés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile d''olive dans une cocotte à fond épais, y faire suer l''oignon et la carotte à feu moyen une dizaine de minutes, jusqu''à ce qu''ils deviennent translucides et souples sans prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Débarrasser l''oignon et la carotte dans une assiette : la saisie se mène ici en deux fournées, et des légumes laissés sur les bords d''une cocotte brûlante noirciraient pendant que la seconde colore, donnant au jus une amertume dont il ne se relève pas. Monter le feu et déposer la moitié des cubes de porc à plat, sans qu''ils se touchent. Les laisser dorer sans les bouger, les retourner face par face jusqu''à ce qu''ils soient colorés partout et presque bruns, les réserver, puis recommencer avec le reste : privée de garniture fumée, la cocotte n''a plus que cette croûte caramélisée pour donner du fond à son jus, et une viande entassée bout au lieu de saisir. Remettre alors dans la cocotte l''oignon, la carotte, toute la viande et les sucs qu''elle a rendus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser l''eau et gratter aussitôt le fond à la cuillère en bois pour décoller les sucs caramélisés. Ajouter le sel fin et poivrer — il n''y a plus de charcuterie pour saler le jus à la place du cuisinier —, porter à petits bouillons puis couvrir et baisser au minimum.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Laisser mijoter environ une heure à frémissement à peine perceptible, en remuant de loin en loin. Piquer la viande : elle doit céder sans résistance sous la pointe du couteau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Incorporer les pruneaux dénoyautés et poursuivre vingt minutes à couvert, juste assez pour qu''ils gonflent et parfument le jus sans se défaire en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le couvercle pour les dix dernières minutes et laisser le liquide réduire jusqu''à une sauce brillante qui nappe la cuillère. Mélanger avec précaution, goûter et rectifier en sel et en poivre seulement à ce moment : la réduction concentre l''assaisonnement, et un jus salé trop tôt devient immangeable une fois réduit.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-026-D2', 'recipe_family', 'Porc aux pruneaux à la cocotte',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-026-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-026-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-026-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2fa9ce3063dc4538cc55dc9444c5d33a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":2,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["sucré du fruit sec","porc caramélisé","oignon confit"],"aroma_families":["fruit sec","viande rôtie","légume fondu"],"target_textures":["viande fondante à la fourchette","pruneau moelleux et gonflé","sauce nappante"],"signature_ingredients":["Épaule de porc crue","Pruneau dénoyauté"],"identity_guardrails":["Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.","La viande doit être saisie en deux fournées et poussée jusqu''au brun : c''est elle seule qui donne au jus la profondeur que la garniture fumée apportait.","La cuisson reste longue et à couvert : un passage rapide à la poêle ne rend pas l''épaule fondante et ne laisse pas les pruneaux parfumer le jus.","Le mouillement se limite à un fond d''eau, pas à un bain : la sauce doit finir réduite et nappante, jamais aqueuse."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Sauté de veau à la corse', 'saute de veau a la corse', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Sauté de veau à la corse', 'Veau braisé aux olives vertes et noires avec concentré de tomate dans le style corse', ds.id, 'SRC-027-D1',
    'Myko', 'editorial', 4, 25, 165, 'facile',
    NULL, NULL,
    'B', 'candidate', '89b7034ac48a419d2a95ab7bc0b03b8f',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['olive saumurée','veau braisé','ail fondu','vin blanc réduit']::text[],
    ARRAY['herbacé méditerranéen','oignon compoté','tomate concentrée']::text[], ARRAY['viande fondante','sauce nappante','olive charnue']::text[],
    ARRAY['Épaule de veau crue','Olive verte dénoyautée','Olive noire']::text[], ARRAY['Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.','Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.','La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale.']::text[],
    ARRAY['blanchiment','saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','sulfites']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans un récipient hermétique, et gagne même à être réchauffé doucement le lendemain. La congélation est possible trois mois à -18 °C, mais mieux vaut congeler la viande et sa sauce sans les olives, dont la chair se ramollit à la décongélation, et les ajouter au réchauffage.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-027'), '{"variant_label":"Version corse : doubler les lardons fumés et allonger le mijotage à deux heures pour une sauce plus courte et plus fumée.","rationale":"Doubler la poitrine fumée et pousser le mijotage à deux heures fait basculer le plat du côté fumé : le gras se rend entièrement dans la sauce, qui devient plus courte et nappe davantage. Le veau y gagne du fondant mais perd sa mâche franche, et la part grimpe fortement en lipides et en sel. La poitrine cesse d''être facultative — sans elle cette version n''existe pas.","operations":[{"op":"set","form":"Lardon fumé cru","quantity":260,"optional":false}],"steps":[{"op":"replace","n":6,"instruction":"Couvrez et maintenez un frémissement à peine perceptible pendant deux heures pleines, en remuant délicatement de loin en loin pour que rien n''attache. C''est ce long tirage qui fait descendre le fumé de la poitrine dans la sauce au lieu de le laisser flotter en surface, et qui amène la viande au point où elle se défait à la cuillère."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
