  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Chauffer le four à 220 °C. Prendre deux aubergines d''environ 280 g pièce, soit à peu près 560 g sur la balance du primeur, qui donnent les 500 g nets une fois les pédoncules coupés. Les rincer et les fendre en deux dans la longueur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Quadriller la chair à la pointe du couteau sans traverser la peau, saler du bout des doigts, badigeonner avec la moitié de l''huile d''olive, puis enfourner les moitiés chair vers le haut 25 minutes : elles doivent s''affaisser et céder sous la cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, hacher menu l''oignon et l''ail. Les faire suer 5 minutes à feu moyen dans le reste d''huile, en visant la transparence plutôt que la coloration.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Retirer d''abord du feu la poêle d''oignon et d''ail, qui attendra la farce sans brunir : douze minutes de plus sur la flamme suffiraient à l''amertume. Porter une casserole d''eau salée à ébullition et y verser le riz. Le cuire une douzaine de minutes seulement, puis l''égoutter tant qu''il reste ferme au cœur : il finira de gonfler dans la farce, puis au four, et un grain déjà tendre s''y déferait en bouillie. L''étaler dans un plat pour qu''il rende sa vapeur au lieu de coller en masse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir les aubergines, les laisser tiédir 5 minutes, puis les évider à la petite cuillère en gardant une paroi d''environ 5 mm. Hacher grossièrement la chair prélevée et la reverser dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter la tomate râpée, le sucre, les herbes de Provence et un tour de poivre. Laisser réduire à découvert une quinzaine de minutes : la farce est au point quand la cuillère y laisse un sillon net.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer du feu et verser le riz égoutté dans la poêle, en le mêlant à la fourchette pour que les grains se répartissent sans s''écraser. Ajouter le persil et le basilic ciselés, laisser la chaleur retomber deux minutes, puis lier avec les deux œufs battus en remuant sans arrêt, pour qu''ils épaississent la farce au lieu de coaguler en filaments.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Garnir les coques en tassant à peine — une farce au riz trop serrée devient compacte — puis couvrir de la totalité du gruyère râpé, deux fois la dose habituelle, qui forme ici une croûte franche et non un voile. Remettre au four 20 minutes à 200 °C, jusqu''à une surface dorée et boursouflée, et laisser reposer 5 minutes : le riz se tient nettement mieux tiède qu''à la sortie.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-031-D1', 'recipe_family', 'Aubergines farcies au riz',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-031-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-031-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-031-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b958e7dca1c55a54de88329d40a58ef4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","fromage gratiné","ail"],"aroma_families":["herbacé","alliacé","fromager"],"target_textures":["chair fondante","farce moelleuse","surface gratinée"],"signature_ingredients":["Aubergine fraîche","Riz long blanc cru","Tomate râpée"],"identity_guardrails":["La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient un simple riz à la tomate.","La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.","Le riz entre dans la farce ferme au cœur : cuit à point avant l''assemblage, il se délite au four et la garniture devient pâteuse."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Aubergines farcies à la crème', 'aubergines farcies a la creme', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Aubergines farcies à la crème', 'Aubergines évidées farcies de bœuf haché à la tomate, la farce liée à la crème', ds.id, 'SRC-031-D2',
    'Myko', 'editorial', 4, 25, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', '94de71b21a048403e827408884897880',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','viande rôtie','ail']::text[],
    ARRAY['herbacé','alliacé','fromager']::text[], ARRAY['chair fondante','farce moelleuse','surface gratinée']::text[],
    ARRAY['Aubergine fraîche','Bœuf haché cru 15 % MG','Tomate râpée']::text[], ARRAY['La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient une simple sauce à la viande.','La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.','La farce se lie à la tomate réduite et à l''œuf, jamais à une béchamel, qui la ferait basculer vers la moussaka.']::text[],
    ARRAY['rôtissage','saisie','réduction','gratinage']::text[], ARRAY[]::text[], ARRAY['lait','œuf']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; réchauffer 15 minutes à 160 °C plutôt qu''au micro-ondes, qui détrempe la croûte. Congélation possible deux mois avant gratinage, mais la coque rend beaucoup d''eau à la décongélation et perd sa tenue.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-031'), '{"variant_label":"Version crémeuse : napper la farce d''un filet de Crème fraîche liquide entière juste avant le passage au gratin.","rationale":"La crème descend dans la farce pendant le gratinage et la détend : la garniture devient onctueuse là où elle était serrée, et le fromage prend au-dessus au lieu d''adhérer directement à la tomate. Le coût est en gras — quatre-vingts grammes de crème entière ajoutent près de deux cent quarante kilocalories au plat — et en netteté, l''acidité de la tomate s''arrondissant jusqu''à perdre son tranchant.","operations":[{"op":"add","form":"Crème fraîche liquide entière","quantity":80,"unit":"g","role":"liaison","optional":false}],"steps":[{"op":"replace","n":8,"instruction":"Garnir les coques en tassant légèrement, napper chacune d''un filet de crème fraîche liquide entière, puis couvrir de gruyère râpé. Remettre au four 20 minutes à 200 °C : la crème s''enfonce dans la farce et la détend pendant que le fromage colore au-dessus. Laisser reposer 5 minutes avant de servir, le temps que le nappage cesse de couler dans le plat."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
