       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-031-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-031-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-031-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('94de71b21a048403e827408884897880'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","viande rôtie","ail"],"aroma_families":["herbacé","alliacé","fromager"],"target_textures":["chair fondante","farce moelleuse","surface gratinée"],"signature_ingredients":["Aubergine fraîche","Bœuf haché cru 15 % MG","Tomate râpée"],"identity_guardrails":["La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient une simple sauce à la viande.","La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.","La farce se lie à la tomate réduite et à l''œuf, jamais à une béchamel, qui la ferait basculer vers la moussaka."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Aubergines farcies à la friteuse à air', 'aubergines farcies a la friteuse a air', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Aubergines farcies à la friteuse à air', 'Aubergines farcies de bœuf haché à la tomate, cuites à la friteuse à air', ds.id, 'SRC-031-D3',
    'Myko', 'editorial', 4, 25, 38, 'facile',
    NULL, NULL,
    'B', 'candidate', '3cb476935fb665c5ce3bc6b65346750d',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','viande rôtie','ail']::text[],
    ARRAY['herbacé','alliacé','fromager']::text[], ARRAY['chair fondante','farce moelleuse','surface gratinée']::text[],
    ARRAY['Aubergine fraîche','Bœuf haché cru 15 % MG','Tomate râpée']::text[], ARRAY['La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient une simple sauce à la viande.','La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.','La farce se lie à la tomate réduite et à l''œuf, jamais à une béchamel, qui la ferait basculer vers la moussaka.']::text[],
    ARRAY['rôtissage','saisie','réduction','gratinage']::text[], ARRAY[]::text[], ARRAY['lait','œuf']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; réchauffer 15 minutes à 160 °C plutôt qu''au micro-ondes, qui détrempe la croûte. Congélation possible deux mois avant gratinage, mais la coque rend beaucoup d''eau à la décongélation et perd sa tenue.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-031'), '{"variant_label":"Cuisson en air fryer : 30 minutes à 180 °C pour les coques, puis 8 minutes une fois garnies et fromagées (chefsimon.com).","rationale":"La friteuse à air remplace le four sur les deux passages : trente minutes à 180 °C pour les coques, huit une fois garnies. L''air brassé assèche la surface bien plus vite qu''un four, ce qui donne une peau ferme et une croûte de fromage rapide, mais la plupart des paniers n''acceptent pas les quatre moitiés d''un coup. Le gain — une douzaine de minutes et la chaleur d''un four — ne vaut donc que si tout tient en un seul passage : en deux fournées, le second rôtissage de trente minutes rend la cuisson plus longue qu''au four, pas plus courte. On perd dans les deux cas le moelleux un peu humide que donne une enceinte pleine.","operations":[],"steps":[{"op":"replace","n":1,"instruction":"Préchauffer le panier de la friteuse à air trois minutes à 180 °C. Prendre deux aubergines d''environ 280 g pièce, soit à peu près 560 g sur la balance du primeur, qui donnent les 500 g nets une fois les pédoncules coupés. Les rincer, les fendre en deux dans la longueur et vérifier qu''elles tiennent à plat dans le panier : entassées, elles cuisent à la vapeur au lieu de rôtir, quitte à les faire en deux fournées."},{"op":"replace","n":2,"instruction":"Quadriller la chair à la pointe du couteau sans traverser la peau, saler du bout des doigts et badigeonner avec la moitié de l''huile d''olive — l''air brassé dessèche vite, et une chair nue se racornit avant de fondre. Ranger les moitiés chair vers le haut et compter 30 minutes à 180 °C : elles doivent s''affaisser et céder sous la cuillère."},{"op":"replace","n":8,"instruction":"Garnir les coques en tassant légèrement, couvrir de gruyère râpé et remettre 8 minutes à 180 °C dans le panier. Surveiller la dernière minute : le souffle chaud brunit le fromage bien plus tôt qu''un four et le brûlerait avant que la farce ne soit chaude à cœur. Laisser reposer 5 minutes avant de servir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

