  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0790f72f403b3089ba9d6d7eed5ebb22'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["pomme compotée","sucré","profond","beurré"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["protéine_fondante","tendre","feuilletage_croustillant"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.","En tourte, la pomme passe en compote : elle doit rester granuleuse et peu sucrée, une purée lisse détrempant le fond et empêchant la pâte de cuire.","Le boyau se retire entièrement : conservé sous la pâte, il se rétracte sans jamais dorer et reste élastique.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tarte tatin de boudin noir aux pommes', 'tarte tatin de boudin noir aux pommes', 'France', 'France',
     'meal', 'tarte salée', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tarte tatin de boudin noir aux pommes', 'Tarte renversée de pommes caramélisées et boudin noir sur pâte feuilletée', ds.id, 'SRC-032-D2',
    'Myko', 'editorial', 4, 30, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd79ad9d71bfeaa6cbb39e21b15d2a1d1',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['pomme caramélisée','sucré','profond','beurré']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['protéine_fondante','tendre','feuilletage_croustillant']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.','La pomme doit rester en quartiers identifiables et caramélisés au fond du moule ; réduite en compote ou remplacée par de la pomme de terre, l''accord sucré-salé se défait et le renversement n''a plus d''objet.','Le boudin cuit sous la pâte, sans saisie et sans boyau : gardé en boyau à l''étouffée, il se rétracte sans jamais dorer et reste élastique.','Le démoulage se fait tiède et dans les cinq minutes : le caramel figé retient les fruits au fond et la tarte sort nue.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['caramélisation','suer','cuisson au four','renversement']::text[], ARRAY[]::text[], ARRAY['lait','gluten']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Version tatin : quartiers de pomme beurrés et rondelles de boudin recouverts de pâte feuilletée piquée, 30 min à 200 °C (marmiton.org).","rationale":"Le montage renversé fait confire les quartiers de pomme dans le beurre et le sucre au fond du moule, puis les couvre d''une abaisse unique. Le boudin, débarrassé de son boyau et couché en rondelles, cuit à l''étouffée sous la pâte : on perd la saisie et le contraste d''une chair croûtée, on gagne un plat qui se démoule entier et se partage. Le feuilletage ajoute du gras à une assiette qui n''en manquait pas, et le démoulage doit se faire tiède, sous peine de voir le caramel figé retenir les fruits au fond.","operations":[{"op":"add","form":"Pâte feuilletée crue","quantity":250,"unit":"g","role":"pâte","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Faites mousser tout le beurre restant dans un moule qui va sur le feu, poudrez du sucre et rangez-y les quartiers de pomme à plat, face bombée dessous et bien serrés. Laissez-les prendre couleur cinq minutes sur feu moyen sans y toucher : ce caramel de fond deviendra le dessus de la tarte au démoulage, et remuer les quartiers l''empêcherait de se former."},{"op":"replace","n":4,"instruction":"Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, pour les 560 g de chair annoncés. Fendez le boyau d''un coup de lame et retirez-le entièrement, puis coupez la chair en rondelles d''un bon centimètre : sous la pâte, le boyau ne trouverait ni chaleur vive ni surface libre pour se tendre, et resterait caoutchouteux."},{"op":"replace","n":5,"instruction":"Répartissez les oignons fondus sur les pommes, rangez les rondelles de boudin par-dessus en une seule couche, puis recouvrez de la pâte feuilletée découpée au diamètre du moule. Piquez-la de plusieurs coups de fourchette, rentrez les bords à l''intérieur du moule pour enfermer la garniture, et enfournez 30 minutes à 200 °C jusqu''à ce que le feuilletage soit sec et cuivré."},{"op":"replace","n":6,"instruction":"Sortez le moule et laissez-le reposer cinq minutes, pas davantage : le caramel se figerait et retiendrait les fruits au fond. Retournez la tarte d''un geste franc sur un plat plus large, salez, donnez deux tours de moulin à poivre sur les pommes maintenant visibles et servez sans attendre, la pâte perdant son croustillant dès qu''elle refroidit sous les fruits."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
