  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Comptez à l''achat quatre pommes à chair ferme, soit environ 450 g de fruits entiers : une fois pelées, évidées et débarrassées des pépins, il en reste près de 320 g de chair. Détaillez-les en quartiers épais et arrosez-les aussitôt du jus de citron pour qu''ils gardent leur teinte claire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Épluchez 280 g d''oignons pour en obtenir 250 g nets, émincez-les finement et laissez-les fondre à couvert dans un tiers du beurre, sur feu très doux : une quinzaine de minutes suffisent pour qu''ils deviennent translucides puis prennent une couleur dorée, sans jamais accrocher au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faites mousser tout le beurre restant dans un moule qui va sur le feu, poudrez du sucre et rangez-y les quartiers de pomme à plat, face bombée dessous et bien serrés. Laissez-les prendre couleur cinq minutes sur feu moyen sans y toucher : ce caramel de fond deviendra le dessus de la tarte au démoulage, et remuer les quartiers l''empêcherait de se former.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, pour les 560 g de chair annoncés. Fendez le boyau d''un coup de lame et retirez-le entièrement, puis coupez la chair en rondelles d''un bon centimètre : sous la pâte, le boyau ne trouverait ni chaleur vive ni surface libre pour se tendre, et resterait caoutchouteux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Répartissez les oignons fondus sur les pommes, rangez les rondelles de boudin par-dessus en une seule couche, puis recouvrez de la pâte feuilletée découpée au diamètre du moule. Piquez-la de plusieurs coups de fourchette, rentrez les bords à l''intérieur du moule pour enfermer la garniture, et enfournez 30 minutes à 200 °C jusqu''à ce que le feuilletage soit sec et cuivré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Sortez le moule et laissez-le reposer cinq minutes, pas davantage : le caramel se figerait et retiendrait les fruits au fond. Retournez la tarte d''un geste franc sur un plat plus large, salez, donnez deux tours de moulin à poivre sur les pommes maintenant visibles et servez sans attendre, la pâte perdant son croustillant dès qu''elle refroidit sous les fruits.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-032-D2', 'recipe_family', 'Tarte tatin de boudin noir aux pommes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-032-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-032-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d79ad9d71bfeaa6cbb39e21b15d2a1d1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["pomme caramélisée","sucré","profond","beurré"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["protéine_fondante","tendre","feuilletage_croustillant"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.","La pomme doit rester en quartiers identifiables et caramélisés au fond du moule ; réduite en compote ou remplacée par de la pomme de terre, l''accord sucré-salé se défait et le renversement n''a plus d''objet.","Le boudin cuit sous la pâte, sans saisie et sans boyau : gardé en boyau à l''étouffée, il se rétracte sans jamais dorer et reste élastique.","Le démoulage se fait tiède et dans les cinq minutes : le caramel figé retient les fruits au fond et la tarte sort nue.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
